function isPresetPackage(item) { return Boolean(item?.preset || presetPackageIds.has(item?.id) || presetPackageNames.has(String(item?.name||'').toLowerCase())); }
function hydratePackage(item) { const official=starterPackages.find(entry=>entry.id===item?.id||entry.name.toLowerCase()===String(item?.name||'').toLowerCase()); return official ? {...item,preset:true,image:official.image,contents:official.contents,components:[]} : item; }
function ensureOfficialPackages(items) { const source=Array.isArray(items)?items:[]; const official=starterPackages.map(template=>{const saved=source.find(item=>item?.id===template.id||String(item?.name||'').toLowerCase()===template.name.toLowerCase()); return hydratePackage({...template,...saved,id:template.id,preset:true,image:template.image,contents:template.contents,components:[]});}); const custom=source.filter(item=>!isPresetPackage(item)); return [...official,...custom]; }
