function fallbackProductPhoto(id,category) { const byId={'TEST-RICE':'assets/reference/grains.png','TEST-HONEY':'assets/reference/pantry.png','TEST-CANDLE':'assets/reference/household.png','TEST-CUSHION':'assets/reference/household.png','TEST-DIFFUSER':'assets/reference/pantry.png','TEST-GIFT':'assets/reference/package-products.png'};return byId[id]||({'Rice & grains':'assets/reference/grains.png','Pantry':'assets/reference/pantry.png','Fresh essentials':'assets/reference/fresh.png','Home & décor':'assets/reference/household.png','Fragrances':'assets/reference/pantry.png','Bags & accessories':'assets/reference/package-products.png','Gift items':'assets/reference/package-products.png'}[category]||''); }
function loadPublicCatalogue() { if(publicCatalogueLoaded||publicCatalogueLoading||!publicSheetsEndpoint)return;publicCatalogueLoading=true;const callback=`treasuresPublicCatalogue${Date.now()}`;const cleanup=()=>{publicCatalogueLoading=false;delete window[callback];};window[callback]=data=>{try{const remoteProducts=(data.products||[]).map(item=>({id:item['Product ID'],name:item.Name,category:item.Category,price:Number(item['Price (₦)']||0),salePrice:Number(item['Sale price (₦)']||0),onSale:String(item['On sale']).toLowerCase()==='true',stock:Number(item.Stock||0),available:String(item.Available).toLowerCase()!=='false',photo:item['Image URL']||fallbackProductPhoto(item['Product ID'],item.Category),testItem:String(item['Product ID']||'').startsWith('TEST-'),costPrice:products.find(p=>p.id===item['Product ID'])?.costPrice})).filter(item=>item.id);const remotePackages=(data.packages||[]).map(item=>({id:item['Package ID'],name:item.Name,price:`₦${Number(item['Price (₦)']||0).toLocaleString()}`,tag:item.Label||'Curated package',image:item['Image URL']||'assets/premium-package.jpeg',contents:item.Contents||'',components:JSON.parse(item.Components||'[]'),available:String(item.Available).toLowerCase()!=='false',installments:Number(item['Pay small small payments']||0)})).filter(item=>item.id);if(Array.isArray(data.products)){products=remoteProducts;saveProducts();}if(remotePackages.length){featuredPackages=remotePackages.map(item=>({...item,costPrice:featuredPackages.find(p=>p.id===item.id)?.costPrice}));savePackages();}if(data.settings){businessRules={...businessRules,deliveryFee:Number(data.settings.deliveryFee||0),paymentInstructions:data.settings.paymentInstructions||businessRules.paymentInstructions,whatsApp:data.settings.whatsApp||businessRules.whatsApp};saveRules();}publicCatalogueLoaded=true;render(location.hash==='#owner'?'owner-overview':'home');}catch(error){showToast('The latest catalogue could not be loaded.');}finally{cleanup();}};const script=document.createElement('script');script.src=`${publicSheetsEndpoint}?action=catalog&callback=${callback}&t=${Date.now()}`;script.onerror=cleanup;document.head.append(script);setTimeout(()=>{if(publicCatalogueLoading)cleanup();},12000);}
function money(value) { return `₦${Number(value).toLocaleString()}`; }
function clean(v){return String(v??'').replace(/[<>"`]/g,'').replace(/'/g,'’').replace(/&/g,'and').trim().slice(0,500);}
function postPublic(body){return fetch(publicSheetsEndpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(body)}).then(r=>r.json());}
async function hashPin(pin){if(!window.crypto?.subtle)return pin;const d=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(`treasures:${pin}`));return [...new Uint8Array(d)].map(b=>b.toString(16).padStart(2,'0')).join('');}
function cartTotal() { return cart.reduce((total,item)=>total+Number(item.price)*item.quantity,0); }
function addToCart(item) { const existing=cart.find(entry=>entry.id===item.id); if(existing) existing.quantity += 1; else cart.push({...item,quantity:1}); saveCart(); }
function syncToSheet(sheet, record) { if(!sheetsEndpoint||!sheetOwnerKey)return Promise.resolve(); const payload={action:'upsert',key:sheetOwnerKey,sheet,record};return fetch(sheetsEndpoint, {method:'POST', mode:'no-cors', headers:{'Content-Type':'text/plain;charset=utf-8'}, body:JSON.stringify(payload)}).catch(()=>showToast('Saved locally. Sheet sync will retry when connected.')); }
function staffRecord(item) { return {'Staff ID':item.id,'Name':item.name,'Role':item.role,'Phone':item.phone||'','Active':true,'Updated at':new Date().toISOString()}; }
function loadFromSheet() { if(!sheetsEndpoint){showToast('Add the Google Apps Script link first.');return;} if(sheetLoadInProgress)return; sheetLoadInProgress=true; const callback=`treasuresSheetData${Date.now()}`; const cleanup=()=>{sheetLoadInProgress=false;delete window[callback];}; window[callback]=data=>{try{const remoteProducts=(data.products||[]).map(item=>({id:item['Product ID'],name:item.Name,category:item.Category,price:Number(item['Price (₦)']||0),stock:Number(item.Stock||0),available:String(item.Available).toLowerCase()!=='false',photo:item['Image URL']||''})).filter(item=>item.id);const remotePackages=(data.packages||[]).map(item=>({id:item['Package ID'],name:item.Name,price:`₦${Number(item['Price (₦)']||0).toLocaleString()}`,tag:item.Label||'Curated package',image:item['Image URL']||'assets/premium-package.jpeg',contents:item.Contents||'',components:JSON.parse(item.Components||'[]'),available:String(item.Available).toLowerCase()!=='false',installments:Number(item['Pay small small payments']||0)})).filter(item=>item.id);const remoteOrders=(data.orders||[]).map(item=>({id:item['Order ID'],name:item['Customer name'],phone:item.Phone,address:item.Address,items:item.Items,total:Number(item['Total (₦)']||0),status:item['Order status']||'Awaiting payment',deliveryDay:item['Delivery day']||'Wednesday',urgent:String(item.Urgent).toLowerCase()==='true',paymentSubmitted:item['Payment status']==='Customer marked paid'})).filter(item=>item.id);const remoteTeam=(data.staff||[]).map(item=>({id:item['Staff ID'],name:item.Name,role:item.Role,phone:item.Phone||''})).filter(item=>item.id);if(remoteProducts.length){products=remoteProducts;saveProducts();}if(remotePackages.length){featuredPackages=remotePackages;savePackages();}if(remoteOrders.length){orders=remoteOrders;saveOrders();selectedOrderId=orders[0].id;selectedOwnerOrderId=orders[0].id;}if(remoteTeam.length){team=remoteTeam;saveTeam();}showToast('Latest data loaded from your Google Sheet.');render(location.hash==='#owner'?'owner-overview':'home');}catch(error){showToast('Sheet data could not be read.');}finally{cleanup();}}; const script=document.createElement('script');script.src=`${sheetsEndpoint}${sheetsEndpoint.includes('?')?'&':'?'}callback=${callback}&t=${Date.now()}`;script.onerror=()=>{cleanup();showToast('Could not load the Sheet yet. Check the Apps Script web-app link.');};document.head.append(script);setTimeout(()=>{if(sheetLoadInProgress)cleanup();},12000);}
function saveRules() { localStorage.setItem(rulesStorageKey, JSON.stringify(businessRules)); }
function uploadedImageUrl(imageId, attempts=12) { return new Promise((resolve,reject)=>{const check=remaining=>{const callback=`treasuresImage${Date.now()}${remaining}`;const cleanup=()=>delete window[callback];window[callback]=data=>{cleanup();if(data?.url){resolve(publicImageUrl(data.url));return;}if(data?.error){reject(new Error(data.error));return;}if(remaining<=1){reject(new Error('Image upload timed out.'));return;}setTimeout(()=>check(remaining-1),700);};const script=document.createElement('script');script.src=`${sheetsEndpoint}?action=image&id=${encodeURIComponent(imageId)}&callback=${callback}&t=${Date.now()}`;script.onerror=()=>{cleanup();if(remaining<=1)reject(new Error('Image could not be read.'));else setTimeout(()=>check(remaining-1),700);};document.head.append(script);};check(attempts);}); }
function readPhoto(file) { return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('The photo could not be read.'));reader.onload=()=>resolve(String(reader.result));reader.readAsDataURL(file);}); }
function canvasPhoto(canvas, quality) { return new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality)); }
async function optimisePhoto(file) { const targetBytes=160*1024;if(file.size<=targetBytes)return {base64:(await readPhoto(file)).split(',')[1],mimeType:file.type||'image/jpeg',name:file.name};const source=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('The photo could not be prepared.'));image.src=URL.createObjectURL(file);});try{let width=Math.min(source.naturalWidth||source.width,1400);let height=Math.round((source.naturalHeight||source.height)*(width/(source.naturalWidth||source.width)));const canvas=document.createElement('canvas');for(let pass=0;pass<6;pass++){canvas.width=width;canvas.height=height;canvas.getContext('2d').drawImage(source,0,0,width,height);for(const quality of [.8,.68,.56,.46]){const blob=await canvasPhoto(canvas,quality);if(blob&&blob.size<=targetBytes){return {base64:(await readPhoto(blob)).split(',')[1],mimeType:'image/jpeg',name:file.name.replace(/\.[^.]+$/,'')+'.jpg'};}}width=Math.round(width*.75);height=Math.round(height*.75);}throw new Error('This photo is still too large. Try a different photo.');}finally{URL.revokeObjectURL(source.src);}}
function uploadProductImage(file) { return new Promise(async(resolve,reject)=>{if(!sheetsEndpoint||!sheetOwnerKey){reject(new Error('Connect Google Sheets before uploading photos.'));return;}try{const photo=await optimisePhoto(file);const imageId=`IMG-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;await fetch(sheetsEndpoint,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'uploadImage',key:sheetOwnerKey,imageId,base64:photo.base64,mimeType:photo.mimeType,name:photo.name})});resolve(await uploadedImageUrl(imageId));}catch(error){reject(error);}}); }
function productRecord(item) { return {'Product ID':item.id,'Name':item.name,'Category':item.category,'Price (₦)':Number(item.price),'Sale price (₦)':Number(item.salePrice||0),'On sale':Boolean(item.onSale),'Stock':Number(item.stock),'Available':item.available!==false,'Image URL':item.photo?.startsWith('data:')?'':item.photo||'','Updated at':new Date().toISOString()}; }
function packageRecord(item) { return {'Package ID':item.id,'Name':item.name,'Price (₦)':Number(String(item.price).replace(/[^0-9]/g,'')),'Label':item.tag,'Image URL':item.image?.startsWith('data:')?'':item.image||'','Contents':item.contents||'','Components':JSON.stringify(packageComponents(item)),'Pay small small payments':Number(item.installments||0),'Available':item.available!==false,'Updated at':new Date().toISOString()}; }
function packageComponents(item) { return Array.isArray(item?.components) ? item.components : []; }
function packageAvailable(item) { if(item?.available===false)return false; if(isPresetPackage(item))return true; return packageComponents(item).every(component=>{const product=products.find(entry=>entry.id===component.productId);return product&&Number(product.stock||0)>=Number(component.quantity||0);}); }
function saveStockActivity() { localStorage.setItem(stockActivityKey, JSON.stringify(stockActivity)); }
function ownerCatalogueV2() { const productRows=products.length?products.map((item,index)=>{const archived=item.available===false;return `<article class="catalogue-row ${archived?'archived-row':''}"><div class="product-initial">${item.name[0]}</div><div><b>${item.name}</b><span>${item.category} · ${item.stock} in stock${archived?' · Archived':''}</span></div><div class="product-ops"><button class="edit-button" data-restock-product="${index}">Restock</button><button class="edit-button" data-edit-product="${index}">Edit</button><button class="text-action ${archived?'restore':'archive'}" data-archive-product="${index}">${archived?'Restore':'Archive'}</button></div></article>`;}).join(''):`<div class="empty-catalogue"><b>Your product list is empty.</b><span>Add the products you actually stock. They can then be used in custom packages.</span></div>`;const low=products.filter(item=>item.available!==false&&Number(item.stock)<=5);const lowRows=low.length?low.map(item=>`<article><div><b>${item.name}</b><span>${item.stock} left · restock soon</span></div><em>Low</em></article>`).join(''):`<div class="empty-catalogue"><b>No low-stock products.</b><span>Stock alerts will appear here when an active item reaches five or fewer.</span></div>`;const activity=stockActivity.slice(0,4);return `<section class="screen owner-screen">${ownerHeader('Catalogue','Products, packages, pricing and stock.')}<div class="quick-actions"><button class="button" data-page="add-product">Add product</button><button class="button secondary" data-page="create-package">Create package</button></div><div class="section-head"><h2>Products</h2><button class="link" data-page="add-product">Add new</button></div><div class="catalogue-products">${productRows}</div><div class="section-head"><h2>Low stock</h2><button class="link">${low.length} item${low.length===1?'':'s'}</button></div><div class="inventory-list">${lowRows}</div><div class="section-head"><h2>Recent stock activity</h2></div><div class="stock-history">${activity.length?activity.map(entry=>`<article><div><b>+${entry.quantity} · ${entry.name}</b><span>${entry.note||'Stock updated'} · ${new Date(entry.at).toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</span></div><em>Added</em></article>`).join(''):`<div class="empty-catalogue"><b>No stock activity yet.</b><span>Every restock will be recorded here.</span></div>`}</div><div class="section-head"><h2>Packages</h2><button class="link" data-page="create-package">Add package</button></div><div class="package-mini-list">${featuredPackages.map((item,index)=>`<article><img src="${item.image}" alt=""/><div><b>${item.name}</b><span>${item.price} · ${packageAvailable(item)?'Available':'Unavailable'}</span></div><button class="edit-button" data-edit-package="${index}">Edit</button></article>`).join('')}</div></section>${ownerNav('owner-catalogue')}`; }
function ownerCatalogueV3() { const testCount=products.filter(item=>item.testItem).length;if(!testCount)return ownerCatalogueV2();return ownerCatalogueV2().replace('<div class="quick-actions">',`<div class="test-catalogue-note"><b>Test catalogue active</b><span>${testCount} temporary items are loaded for review.</span><button data-clear-test-catalogue>Remove test items</button></div><div class="quick-actions">`); }
function restockProductPage() { const item=products[restockingProduct];if(!item){return ownerCatalogueV2();}return `<section class="screen owner-screen">${ownerHeader('Restock product',item.name)}<form id="restock-form" class="form-card"><div class="stock-summary"><b>${item.stock}</b><span>currently in stock</span></div><label>Quantity received<input required autofocus name="quantity" type="number" min="1" placeholder="e.g. 12"/></label><label>Note <span>(optional)</span><input name="note" placeholder="e.g. Supplier delivery"/></label><button class="button" type="submit">Add to stock</button></form></section>${ownerNav('owner-catalogue')}`; }
function packagesPageV2() { return `<section class="screen packages-screen">${customerHeader('home')}<div class="package-page-intro"><div class="eyebrow">Treasures by Mudaso</div><h1>Curated packages</h1><p>Choose a package, then add it to your bag.</p></div><div class="package-list">${featuredPackages.map((item,index)=>{const available=packageAvailable(item);return `<article class="catalogue-package ${available?'':'package-unavailable'}"><button class="package-poster" data-package-detail="${index}"><img src="${item.image}" alt="${item.name}"/></button><div class="package-action"><div><span>${available?item.tag:'Currently unavailable'}</span><strong>${item.name}</strong></div><button class="add-package" data-add-package="${index}" ${available?'':'disabled'}>${available?'Add to bag <b>+</b>':'Unavailable'}</button></div></article>`;}).join('')}</div></section>${customerNav('packages')}`; }
function packageDetailV2() { const item=featuredPackages[selectedPackageIndex];const available=packageAvailable(item);const contents=item.contents||'A carefully selected mix of premium grocery essentials.';const installments=Number(item.installments||0);const price=Number(String(item.price).replace(/[^0-9]/g,''));const plan=installments>1?`<section class="pay-small-small"><span>Pay small small</span><b>${installments} payments of about ${money(Math.ceil(price/installments))}</b><small>Your package is prepared after the final payment.</small><button class="button secondary" data-add-package="${selectedPackageIndex}|plan" ${available?'':'disabled'}>Choose ${installments}-part plan</button></section>`:'';return `<section class="screen package-detail">${customerHeader('packages')}<img class="detail-poster" src="${item.image}" alt="${item.name}"/><div class="eyebrow">${available?item.tag:'Currently unavailable'}</div><h1>${item.name}</h1><div class="detail-price">${item.price}</div><p class="muted">A considered grocery package, professionally packed and delivered with care.</p><section class="included-card"><h2>What’s included</h2><p>${contents}</p><div><span>✓ Premium quality</span><span>✓ Carefully packed</span><span>✓ Delivery available</span></div></section>${plan}<button class="button checkout-button" data-add-package="${selectedPackageIndex}" ${available?'':'disabled'}>${available?`Pay in full · ${item.price}`:'Currently unavailable'}</button></section>${customerNav('packages')}`; }
function ownerOrderDetailV2() { const o=orders.find(item=>item.id===selectedOwnerOrderId)||orders[0];const next=nextStatus(o.status);const itemList=(o.items||'').split(', ').filter(Boolean);const picked=o.pickedItems||[];const deliveryTeam=team.filter(member=>member.role==='Delivery person');const deliveryOptions=deliveryTeam.length?`<option value="">Choose delivery person</option>${deliveryTeam.map(member=>`<option ${o.deliveryPerson===member.name?'selected':''}>${member.name}</option>`).join('')}`:`<option value="">Add a delivery person in Staff</option>`;const items=itemList.map((item,index)=>`<li class="${picked.includes(index)?'picked':''}"><button data-pick-item="${o.id}|${index}" aria-pressed="${picked.includes(index)}"><span class="pick-mark">${picked.includes(index)?'✓':' '}</span><span>${item}</span></button></li>`).join('');const payment=o.status==='Awaiting payment'?(o.paymentSubmitted?'Customer marked paid — ready to confirm':'Awaiting customer payment'):'Confirmed';const packCheck=o.status==='Packing'?`<form id="packing-check-form" data-order-id="${o.id}" class="packing-check"><label><input type="checkbox" name="packed" ${o.packed?'checked':''}/><span>I have checked and sealed this order.</span></label><button class="button secondary" type="submit">Save packing check</button></form>`:'';return `<section class="screen owner-screen order-detail">${ownerHeader(o.id,'Customer order and fulfilment')}<div class="detail-status"><span class="status ${o.type||''}">${o.status}</span>${o.urgent?'<b>Urgent delivery</b>':''}</div><section class="detail-block"><h2>Customer</h2><p><b>${o.name}</b><br>${o.phone||'Phone to be confirmed'}<br>${o.address||o.items}</p></section><section class="detail-block"><div class="pick-heading"><h2>Pick checklist</h2><span>${picked.length} / ${itemList.length} picked</span></div><p class="pick-help">Items can only be checked after payment is confirmed.</p><ul class="pick-list">${items}</ul></section><section class="detail-block"><h2>Order notes & substitutions</h2><form id="order-notes-form" data-order-id="${o.id}" class="notes-form"><label>Internal note<textarea name="internalNote" placeholder="e.g. Call customer on arrival">${o.internalNote||''}</textarea></label><label>Substitution agreed with customer<textarea name="substitutionNote" placeholder="e.g. Swapped unavailable item for equivalent">${o.substitutionNote||''}</textarea></label><button class="button secondary" type="submit">Save notes</button></form></section><section class="detail-block"><h2>Fulfilment</h2><div class="fulfilment-grid"><span>Payment</span><b>${payment}</b><span>Delivery day</span><b>${o.deliveryDay||'Wednesday'}</b><span>Delivery person</span><b>${o.deliveryPerson||'Not assigned'}</b></div>${packCheck}<form id="delivery-assignment-form" data-order-id="${o.id}" class="inline-form"><select name="deliveryPerson">${deliveryOptions}</select><button class="button" type="submit">Assign</button></form></section>${next?`<button class="button checkout-button" data-advance-order="${o.id}">Mark as ${next}</button>`:'<div class="completed-order">✓ Order completed</div>'}</section>${ownerNav('owner-orders')}`; }
function deliveryManifest() { const queue=orders.filter(o=>(o.deliveryDay||'Wednesday')===ownerDeliveryDay&&o.status==='Out for delivery');return `<section class="screen owner-screen manifest-screen">${ownerHeader(`${ownerDeliveryDay} delivery run`,'A hand-off list for the delivery person.')}<div class="day-tabs">${['Monday','Wednesday','Friday'].map(day=>`<button data-manifest-day="${day}" class="${ownerDeliveryDay===day?'active':''}">${day}</button>`).join('')}</div><div class="manifest-summary"><b>${queue.length} delivery stop${queue.length===1?'':'s'}</b><span>Only orders marked “Out for delivery” appear here.</span></div><div class="manifest-list">${queue.length?queue.map((o,index)=>`<article><div class="stop-number">${index+1}</div><div><b>${o.name}</b><span>${o.address||'Address to be confirmed'}</span><small>${o.phone||'Phone to be confirmed'} · ${o.deliveryPerson||'Unassigned'}</small></div></article>`).join(''):`<div class="empty-catalogue"><b>No orders are out for delivery.</b><span>Complete packing and assign a delivery person first.</span></div>`}</div><button class="button secondary checkout-button" data-print-manifest>Print or save this list</button></section>${ownerNav('owner-orders')}`; }
function ownerOrderDetailV3() { const o=orders.find(item=>item.id===selectedOwnerOrderId)||orders[0];const fee=Number(o.dispatchFee ?? businessRules.deliveryFee ?? 0);return ownerOrderDetailV2().replace(`<span>Delivery person</span><b>${o.deliveryPerson||'Not assigned'}</b>`,`<span>Dispatch fee</span><b>${money(fee)}</b>`).replace(/<form id="delivery-assignment-form"[\s\S]*?<\/form>/,`<form id="dispatch-fee-form" data-order-id="${o.id}" class="inline-form"><input name="dispatchFee" type="number" min="0" value="${fee}" aria-label="Dispatch fee" placeholder="Dispatch fee"/><button class="button" type="submit">Save fee</button></form>`); }
function ownerOrderDetailV4() { const o=orders.find(item=>item.id===selectedOwnerOrderId)||orders[0];const review=o.status==='Awaiting payment'?`<section class="payment-review-card ${o.paymentSubmitted?'ready':''}"><div><b>${o.paymentSubmitted?'Payment marked as sent':'Awaiting customer payment'}</b><span>${o.paymentSubmitted?'Check the transfer, then confirm to release this order to picking.':'The customer has not marked payment as sent yet.'}</span></div>${o.paymentSubmitted?`<button class="button" data-confirm-payment="${o.id}">Confirm payment</button>`:''}</section>`:'';return ownerOrderDetailV3().replace('</div><section class="detail-block"><h2>Customer</h2>',`</div>${review}<section class="detail-block"><h2>Customer</h2>`); }
function ownerOrderDetailV5() { const o=orders.find(item=>item.id===selectedOwnerOrderId)||orders[0];const start=o.status==='Ready to pick'?`<section class="fulfilment-next"><div><b>Ready to pick</b><span>Start when the order is in front of you.</span></div><button class="button" data-start-picking="${o.id}">Start picking</button></section>`:'';let view=ownerOrderDetailV4().replace('</div><section class="detail-block"><h2>Customer</h2>',`</div>${start}<section class="detail-block"><h2>Customer</h2>`);if(o.status==='Packing')view=view.replace(/<form id="packing-check-form"[\s\S]*?<\/form>/,`<div class="packing-ready"><b>Everything picked.</b><span>Check the order is complete, then hand it to dispatch.</span><button class="button" data-finish-packing="${o.id}">Packed & ready for dispatch</button></div>`);return view; }
function deliveryManifestV2() { const queue=orders.filter(o=>(o.deliveryDay||'Wednesday')===ownerDeliveryDay&&o.status==='Out for delivery');return `<section class="screen owner-screen manifest-screen">${ownerHeader(`${ownerDeliveryDay} dispatch hand-off`,'Packages ready for your dispatch service.')}<div class="day-tabs">${['Monday','Wednesday','Friday'].map(day=>`<button data-manifest-day="${day}" class="${ownerDeliveryDay===day?'active':''}">${day}</button>`).join('')}</div><div class="manifest-summary"><b>${queue.length} package${queue.length===1?'':'s'} ready for dispatch</b><span>Only packed orders sent to dispatch appear here.</span></div><div class="manifest-list">${queue.length?queue.map((o,index)=>`<article><div class="stop-number">${index+1}</div><div><b>${o.name}</b><span>${o.address||'Address to be confirmed'}</span><small>${o.phone||'Phone to be confirmed'} · Dispatch fee ${money(Number(o.dispatchFee ?? businessRules.deliveryFee ?? 0))}</small></div></article>`).join(''):`<div class="empty-catalogue"><b>No packages are with dispatch.</b><span>Complete packing, then mark an order as sent to dispatch.</span></div>`}</div><button class="button secondary checkout-button" data-print-manifest>Print or save this list</button></section>${ownerNav('owner-orders')}`; }
function businessSettingsV2() { return businessSettings().replace('Delivery & payment','Dispatch & payment').replace('Standard delivery fee','Standard dispatch fee'); }
function homeV2() { const install=window.matchMedia&&window.matchMedia('(display-mode: standalone)').matches?'':`<button class="install-app" data-install-app>⌄ Install Treasures app</button>`;return home().replace('<section class="schedule">',`${install}<section class="schedule">`); }
function homeV3() { return homeV2().replace('<section class="schedule">',`<button class="sale-hero" data-shop-sale><span>Limited offers</span><b>Shop the sale</b><i>›</i></button><section class="schedule">`).replace('<strong>Household</strong>','<strong>Home & décor</strong>'); }
function salePrice(product) { return product.onSale&&Number(product.salePrice)>0?Number(product.salePrice):Number(product.price); }
function shopV2() { if (!products.length) return `<section class="screen placeholder">${customerHeader('home')}<div class="placeholder-box"><div class="eyebrow">New catalogue</div><h1>Shop Treasures</h1><p class="muted">The owner is adding groceries, home décor and lifestyle items.</p><button class="button" data-page="packages">Browse packages</button></div></section>${customerNav('shop')}`;const visible=products.map((product,index)=>({...product,index})).filter(product=>product.available!==false&&(!shopQuery||`${product.name} ${product.category}`.toLowerCase().includes(shopQuery.toLowerCase()))&&(activeShopCategory==='All'||(activeShopCategory==='Sale'?product.onSale:product.category===activeShopCategory)));const filters=['All','Sale',...new Set(products.map(p=>p.category))];return `<section class="screen shop-screen">${customerHeader('home')}<div class="eyebrow">Treasures by Mudaso</div><h1>${activeShopCategory==='Sale'?'Sale':'Shop Treasures'}</h1><input class="shop-search" data-shop-search value="${shopQuery}" placeholder="Search groceries, décor and gifts" aria-label="Search products"/><div class="shop-filters">${filters.map(category=>`<button data-shop-category="${category}" class="${activeShopCategory===category?'active':''} ${category==='Sale'?'sale-filter':''}">${category==='Sale'?'Sale ✦':category}</button>`).join('')}</div><div class="shop-grid">${visible.length?visible.map(product=>{const soldOut=Number(product.stock)<=0;const price=salePrice(product);return `<article class="shop-product ${soldOut?'sold-out':''}">${product.photo?`<img src="${product.photo}" alt="${product.name}"/>`:`<div class="product-initial">${product.name[0]}</div>`}${product.onSale?'<span class="sale-badge">Sale</span>':''}<div><small>${product.category}${soldOut?' · Sold out':` · ${product.stock} left`}</small><strong>${product.name}</strong><b>${product.onSale?`<s>${money(product.price)}</s> ${money(price)}`:money(price)}</b></div><button data-add-product="${product.index}" ${soldOut?'disabled':''}>${soldOut?'Sold out':'Add <span>+</span>'}</button></article>`}).join(''):'<div class="empty-catalogue"><b>No treasures found.</b><span>Try another category or search term.</span></div>'}</div></section>${customerNav('shop')}`; }
function addProductV2(index) { const item=Number.isInteger(index)?products[index]:null;const photo=item?.photo?`<img class="product-photo-preview" src="${item.photo}" alt="Current product photo"/>`:'';const categories=['Pantry','Rice & grains','Fresh essentials','Home & décor','Fragrances','Bags & accessories','Gift items'];return `<section class="screen owner-screen">${ownerHeader(item?'Edit product':'Add a product','Groceries, home décor and lifestyle treasures.')}<form id="product-form" data-product-index="${item?index:''}" data-existing-photo="${item?.photo||''}" class="form-card"><label>Product name<input required name="name" value="${item?.name||''}" placeholder="e.g. Scented candle, Basmati rice"/></label><label>Category<select required name="category"><option value="">Choose a category</option>${categories.map(category=>`<option ${item?.category===category?'selected':''}>${category}</option>`).join('')}</select></label><div class="form-row"><label>Regular price (₦)<input required name="price" type="number" min="0" value="${item?.price||''}" placeholder="0"/></label><label>Stock quantity<input required name="stock" type="number" min="0" value="${item?.stock||''}" placeholder="0"/></label></div><label class="toggle"><input name="onSale" type="checkbox" ${item?.onSale?'checked':''}/><span>Show this item in the Sale</span></label><label>Sale price (₦) <span>(only if on sale)</span><input name="salePrice" type="number" min="0" value="${item?.salePrice||''}" placeholder="Set a discounted price"/></label><label>Product photo <span>(optional)</span><input name="photoUpload" type="file" accept="image/*"/><small class="photo-help">Choose a photo from this device. No link needed.</small>${photo}</label><label class="toggle"><input name="available" type="checkbox" ${item?.available!==false?'checked':''}/><span>Available to customers</span></label><button class="button" type="submit">${item?'Save changes':'Save product'}</button></form></section>${ownerNav('owner-catalogue')}`; }
function ownerMoreV2() { const setup=`<details class="sheet-setup"><summary>Set up the live connection</summary><ol><li>Open your Sheet, then choose <b>Extensions → Apps Script</b>.</li><li>Replace the starter code with the file below and save it.</li><li>Choose <b>Deploy → New deployment → Web app</b>; run as you and allow access to anyone with the link.</li><li>Copy the web-app link ending in <b>/exec</b>, then paste it above.</li></ol><a href="google-apps-script.gs" target="_blank" rel="noreferrer">Open the ready-to-paste Apps Script</a></details>`;return ownerMore().replace('</div><button class="owner-lock"',`${setup}</div><button class="owner-lock"`); }
function ownerOrdersV2() { return ownerOrders().replace('<div class="section-head"><h2>Workflow</h2></div>','<div class="section-head"><h2>Workflow</h2><button class="link" data-page="delivery-manifest">Delivery run</button></div>'); }
function ownerOrdersV3() { return ownerOrdersV2().replace(/<button class="advance-order" data-advance-order="([^"]+)">Payment confirmed<\/button>/g,(match,id)=>{const order=orders.find(item=>item.id===id);return order?.paymentSubmitted?`<button class="advance-order payment-review" data-open-order="${id}">Review payment</button>`:`<span class="payment-waiting">Awaiting customer payment</span>`;}); }
function createOrderId() { return `TBM-${Date.now().toString().slice(-8)}${Math.random().toString(36).slice(2,5).toUpperCase()}`; }
async function placeCheckout(form){
  const button=form.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;
  const values=Object.fromEntries(new FormData(form));
  customerProfile={name:values.name,phone:values.phone,address:values.address,day:values.day||'Wednesday'};saveCustomerProfile();
  const id=createOrderId();const plan=cart.length===1?Number(cart[0].installments||0):0;
  const record={id,name:clean(values.name),phone:clean(values.phone),address:clean(values.address),items:clean(cart.map(i=>`${i.quantity} × ${i.name}`).join(', ')),total:cartTotal(),dispatchFee:Number(businessRules.deliveryFee||0),status:'Awaiting payment',type:'payment',paid:false,deliveryDay:values.day||'Wednesday',urgent:Boolean(form.elements.urgent?.checked),installments:plan,installmentsPaid:0,balance:cartTotal(),createdAt:new Date().toISOString()};
  const lines=cart.map(i=>({kind:i.kind,id:i.kind==='package'?i.packageId:i.id,quantity:i.quantity,installments:Number(i.installments||0)}));
  try{const res=await postPublic({action:'createOrder',record:orderRecord(record),lines});if(!res.ok){showToast(res.error||'Order could not be placed.');button.disabled=false;return;}record.total=res.total;record.balance=res.total;record.dispatchFee=Number(res.dispatchFee??record.dispatchFee);}
  catch(e){showToast('Could not reach the shop. Check your connection and try again.');button.disabled=false;return;}
  orders.unshift(record);selectedOrderId=id;saveOrders();cart=[];saveCart();publicCatalogueLoaded=false;loadPublicCatalogue();render('confirmation');
}
function orderRecord(item) { return {'Order ID':item.id,'Customer name':item.name,'Phone':item.phone||'','Address':item.address||'','Delivery day':item.deliveryDay||'','Urgent':Boolean(item.urgent),'Items':item.items,'Total (₦)':Number(item.total||0),'Payment status':item.status==='Awaiting payment'?(item.paymentSubmitted?'Customer marked paid':'Awaiting payment'):'Confirmed','Order status':item.status,'Pay small small payments':Number(item.installments||0),'Payments confirmed':Number(item.installmentsPaid||0),'Balance (₦)':Number(item.balance??item.total??0),'Dispatch fee (₦)':Number(item.dispatchFee ?? businessRules.deliveryFee ?? 0),'Internal note':item.internalNote||'','Substitution note':item.substitutionNote||'','Packing checked':Boolean(item.packed),'Picked items':JSON.stringify(item.pickedItems||[]),'Paid at':item.status!=='Awaiting payment'?(item.paidAt||(item.paidAt=new Date().toISOString())):'','Created at':item.createdAt||'','Updated at':new Date().toISOString()}; }
function brand() { return `<div class="brand"><div class="mark">TM</div><div><div class="brand-name">Treasures by Mudaso</div><div class="brand-sub">Thoughtful. Quality. Trusted.</div></div></div>`; }
function icon(name) {
  const paths = { search:'<circle cx="11" cy="11" r="5.5"/><path d="m15.5 15.5 4 4"/>', bag:'<path d="M5 8.5h14l-1 11H6l-1-11Z"/><path d="M8.5 9V6.5a3.5 3.5 0 0 1 7 0V9"/>', truck:'<path d="M3 5h11v10H3z"/><path d="M14 9h3l3 3v3h-6z"/><circle cx="7" cy="17" r="1.5"/><circle cx="17" cy="17" r="1.5"/>', home:'<path d="m3 11 9-7 9 7v9H3z"/><path d="M9 20v-6h6v6"/>', grid:'<rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/>', gift:'<path d="M4 9h16v11H4z"/><path d="M12 9v11M3 5h18v4H3z"/><path d="M12 5C9 1 5 4 7 6m5-1c3-4 7-1 5 1"/>', receipt:'<path d="M6 3h12v18l-2-1.5-2 1.5-2-1.5-2 1.5-2-1.5L6 21z"/><path d="M9 8h6M9 12h6M9 16h4"/>', users:'<circle cx="9" cy="8" r="3"/><path d="M3.5 20a5.5 5.5 0 0 1 11 0"/><path d="M16 5.5a3 3 0 0 1 0 5.8M17 14.5a4.8 4.8 0 0 1 3.5 5"/>', chart:'<path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/>', box:'<path d="m3 7 9-4 9 4-9 4-9-4Z"/><path d="M3 7v10l9 4 9-4V7M12 11v10"/>', more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>' };
  return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]}</svg>`;
}
function customerNav(active) { return `<nav class="nav" aria-label="Customer navigation">${[['home','Home','home'],['shop','Shop','grid'],['packages','Packages','gift'],['orders','Orders','receipt']].map(([id,label,image]) => `<button class="${active === id ? 'active' : ''}" data-page="${id}">${icon(image)}<span>${label}</span></button>`).join('')}</nav>`; }
function ownerNav(active) { return `<nav class="owner-nav" aria-label="Owner navigation">${[['owner-overview','Overview','home'],['owner-orders','Orders','receipt'],['owner-catalogue','Catalogue','box'],['owner-customers','Customers','users'],['owner-more','More','more']].map(([id,label,image]) => `<button class="${active === id ? 'active' : ''}" data-page="${id}">${icon(image)}<span>${label}</span></button>`).join('')}</nav>`; }
function customerHeader(back) { return `<header class="topbar">${back ? `<button class="back-button" data-page="${back}" aria-label="Go back">‹</button>${brand()}` : `<div class="brand-wrap">${brand()}</div><div class="header-actions"><button class="round-button" data-open-search aria-label="Search products">${icon('search')}</button>`}<button class="bag-button" data-page="bag" aria-label="Open shopping bag">${icon('bag')}<span>${cartCount}</span></button>${back ? '' : '</div>'}</header>`; }
function ownerGate() { const hasPin=Boolean(localStorage.getItem(ownerPinKey)); return `<section class="screen owner-gate"><div class="owner-gate-top"><div class="gate-monogram">TM</div><span>Private owner access</span></div><div class="owner-gate-intro"><div class="owner-gate-lock" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M7.5 10V7.4a4.5 4.5 0 0 1 9 0V10M6.4 10h11.2c.9 0 1.6.7 1.6 1.6v7.2c0 .9-.7 1.6-1.6 1.6H6.4c-.9 0-1.6-.7-1.6-1.6v-7.2c0-.9.7-1.6 1.6-1.6Z"/></svg></div><div class="eyebrow">Treasures by Mudaso</div><h1>${hasPin?'Welcome back.':'Set up your private space.'}</h1><p>${hasPin?'Enter your access code to manage orders, stock and sales.':'Create a simple access code to keep the business workspace private on this device.'}</p></div><div class="owner-gate-card"><div class="gate-card-heading"><div><span>Owner workspace</span><b>${hasPin?'Unlock dashboard':'Secure this device'}</b></div><i>✦</i></div><form id="owner-gate-form" class="form-card" data-mode="${hasPin?'unlock':'setup'}"><label>Access code<input required name="pin" inputmode="numeric" autocomplete="current-password" pattern="[0-9]{4,8}" minlength="4" maxlength="8" type="password" placeholder="••••"/></label>${hasPin?'':`<label>Confirm access code<input required name="confirmPin" inputmode="numeric" autocomplete="new-password" pattern="[0-9]{4,8}" minlength="4" maxlength="8" type="password" placeholder="••••"/></label>`}<button class="button" type="submit"><span>${hasPin?'Unlock owner workspace':'Save access code'}</span><b>›</b></button></form><p class="owner-gate-note"><span>⌁</span>Your Google Sheet remains protected by your Google account. This code only locks owner tools on this device.</p></div><p class="owner-gate-return">Not the owner? <button data-page="home">Return to customer shop</button></p></section>`; }

function home() { return `<section class="screen">${customerHeader()}<section class="hero"><img class="hero-art" src="assets/reference/hero-products.png" alt="Selected premium grocery products"/><div class="hero-copy"><h1>Delivering<br><em>care</em> to your<br>door.</h1><div class="hero-rule"></div><p>Quality groceries<br>for a healthier,<br>happier home.</p><button class="button gold" data-page="shop">Shop now <span>›</span></button></div></section><section class="schedule"><div class="schedule-intro">${icon('truck')}<small><b>Delivering care<br>to your door.</b></small></div><div class="day"><span>▣</span>Monday</div><div class="day"><span>▣</span>Wednesday</div><div class="day"><span>▣</span>Friday</div></section><div class="section-head"><h2>Shop by category</h2><button class="link" data-page="shop">See all</button></div><div class="category-grid"><button class="category"><img src="assets/reference/pantry.png" alt="Pantry items"/><strong>Pantry</strong></button><button class="category"><img src="assets/reference/grains.png" alt="Rice and grains"/><strong>Rice & grains</strong></button><button class="category"><img src="assets/reference/household.png" alt="Household essentials"/><strong>Household</strong></button><button class="category"><img src="assets/reference/fresh.png" alt="Fresh essentials"/><strong>Fresh essentials</strong></button></div><div class="section-head"><h2>Curated packages</h2><button class="link" data-page="packages">View all</button></div><article class="package-card"><img src="assets/reference/package-products.png" alt="Curated premium grocery package"/><div><h3>Curated packages</h3><div class="package-rule"></div><p>Carefully selected essentials for your home.</p><button class="button gold" data-page="packages">Explore packages <span>›</span></button></div></article></section>${customerNav('home')}`; }
function packagesPage() { return `<section class="screen packages-screen">${customerHeader('home')}<div class="package-page-intro"><div class="eyebrow">Treasures by Mudaso</div><h1>Curated packages</h1><p>Choose a package, then add it to your bag.</p></div><div class="package-list">${featuredPackages.map((item,index) => `<article class="catalogue-package"><button class="package-poster" data-package-detail="${index}"><img src="${item.image}" alt="${item.name}"/></button><div class="package-action"><div><span>${item.tag}</span><strong>${item.name}</strong></div><button class="add-package" data-add-package="${index}">Add to bag <b>+</b></button></div></article>`).join('')}</div></section>${customerNav('packages')}`; }
function packageDetail() { const item=featuredPackages[selectedPackageIndex]; const contents=item.contents||'A carefully selected mix of premium grocery essentials.'; return `<section class="screen package-detail">${customerHeader('packages')}<img class="detail-poster" src="${item.image}" alt="${item.name}"/><div class="eyebrow">${item.tag}</div><h1>${item.name}</h1><div class="detail-price">${item.price}</div><p class="muted">A considered grocery package, professionally packed and delivered with care.</p><section class="included-card"><h2>What’s included</h2><p>${contents}</p><div><span>✓ Premium quality</span><span>✓ Carefully packed</span><span>✓ Delivery available</span></div></section><button class="button checkout-button" data-add-package="${selectedPackageIndex}">Add to bag · ${item.price}</button></section>${customerNav('packages')}`; }
function shop() { if (!products.length) return `<section class="screen placeholder">${customerHeader('home')}<div class="placeholder-box"><div class="eyebrow">New catalogue</div><h1>Shop essentials</h1><p class="muted">The owner is adding the first individual products. Our curated packages are ready now.</p><button class="button" data-page="packages">Browse packages</button></div></section>${customerNav('shop')}`; const visible=products.map((product,index)=>({...product,index})).filter(product=>product.available!==false&&(!shopQuery||`${product.name} ${product.category}`.toLowerCase().includes(shopQuery.toLowerCase()))&&(activeShopCategory==='All'||product.category===activeShopCategory)); return `<section class="screen shop-screen">${customerHeader('home')}<div class="eyebrow">Your catalogue</div><h1>Shop essentials</h1><input class="shop-search" data-shop-search value="${shopQuery}" placeholder="Search products" aria-label="Search products"/><div class="shop-filters">${['All',...new Set(products.map(p=>p.category))].map(category=>`<button data-shop-category="${category}" class="${activeShopCategory===category?'active':''}">${category}</button>`).join('')}</div><div class="shop-grid">${visible.length?visible.map(product=>{const soldOut=Number(product.stock)<=0;return `<article class="shop-product ${soldOut?'sold-out':''}">${product.photo?`<img src="${product.photo}" alt="${product.name}"/>`:`<div class="product-initial">${product.name[0]}</div>`}<div><small>${product.category}${soldOut?' · Sold out':` · ${product.stock} left`}</small><strong>${product.name}</strong><b>${money(product.price)}</b></div><button data-add-product="${product.index}" ${soldOut?'disabled':''}>${soldOut?'Sold out':'Add <span>+</span>'}</button></article>`}).join(''):'<div class="empty-catalogue"><b>No products found.</b><span>Try another category or search term.</span></div>'}</div></section>${customerNav('shop')}`; }
function statusStep(status) { return ({'Awaiting payment':1,'Payment confirmed':2,'Ready to pick':3,'Picking':3,'Packing':4,'Out for delivery':5,'Completed':6})[status] || 1; }
function statusNote(status) { return ({'Awaiting payment':['Awaiting payment','Please make payment to secure your delivery slot.'],'Payment confirmed':['Payment confirmed','Your payment is confirmed. We will begin picking soon.'],'Ready to pick':['Ready to pick','Your order is queued for the next picking run.'],'Picking':['Being picked','We are selecting your items with care.'],'Packing':['Being packed','Your groceries are being packed for delivery.'],'Out for delivery':['Out for delivery','Your order is on its way.'],'Completed':['Delivered','Your order has been completed.']})[status] || ['Order received','We have received your order.']; }
function customerOrders() { const order=orders.find(item=>item.id===selectedOrderId)||orders[0]; const step=statusStep(order.status); const labels=['Order','Payment','Picking','Packing','Delivery']; const numbers=[1,2,3,4,5]; const note=statusNote(order.status); const history=orders.map(item=>`<button class="history-order ${item.id===order.id?'selected':''}" data-track-order="${item.id}"><div><strong>${item.id}</strong><span>${item.deliveryDay||'Wednesday'} delivery · ${item.items}</span></div><div><b class="status ${item.type||''}">${item.status}</b><i>›</i></div></button>`).join(''); const support=businessRules.whatsApp?`<a class="support-link" target="_blank" rel="noreferrer" href="https://wa.me/${businessRules.whatsApp.replace(/[^0-9]/g,'')}?text=${encodeURIComponent(`Hello Treasures by Mudaso, I need help with order ${order.id}.`)}">Need help? Chat with us on WhatsApp</a>`:''; return `<section class="screen orders-screen">${customerHeader('home')}<div class="eyebrow">My orders</div><h1>Track your order</h1><p class="muted">Use your order number to see its live progress.</p><form id="tracking-form" class="track-form"><input aria-label="Order number" name="order" value="${order.id}" placeholder="e.g. TBM-1042"/><button class="button" type="submit">Track order</button></form><article class="tracking-card"><div class="tracking-top"><div><span>Order</span><strong>${order.id}</strong></div><b>${order.status==='Awaiting payment'?'Payment pending':'In progress'}</b></div><p>${order.items} · ${order.deliveryDay||'Wednesday'} delivery</p><div class="progress-line">${numbers.map(number=>`<span class="${number<step?'done':number===step?'current':''}">${number}</span>${number<5?'<i></i>':''}`).join('')}</div><div class="progress-labels">${labels.map(label=>`<span>${label}</span>`).join('')}</div><div class="tracking-note"><b>${note[0]}</b><span>${note[1]}</span></div></article><div class="section-head order-history-head"><h2>Recent orders</h2><span>${orders.length} total</span></div><div class="history-list">${history}</div>${support}</section>${customerNav('orders')}`; }
function bag() { if(!cart.length)return `<section class="screen placeholder">${customerHeader('home')}<div class="placeholder-box"><div class="eyebrow">Your bag</div><h1>Nothing here yet.</h1><p class="muted">Choose a package or add products from the shop.</p><button class="button" data-page="packages">Explore packages</button></div></section>${customerNav('packages')}`; return `<section class="screen checkout-screen">${customerHeader('packages')}<div class="eyebrow">Your order</div><h1>Shopping bag</h1><div class="bag-list">${cart.map((item,index)=>`<article class="bag-item">${item.image?`<img src="${item.image}" alt="${item.name}"/>`:'<div class="product-initial">'+item.name[0]+'</div>'}<div><strong>${item.name}</strong><small>${item.kind==='package'?'Curated package':'Individual item'}</small><b>${money(item.price)}</b></div><div class="quantity"><button data-cart-change="${index}|-1">−</button><span>${item.quantity}</span><button data-cart-change="${index}|1">+</button></div></article>`).join('')}</div><div class="total"><span>Subtotal</span><b>${money(cartTotal())}</b><span>Delivery</span><b>Set at checkout</b><strong>Total <em>${money(cartTotal())}</em></strong></div><button class="button checkout-button" data-page="checkout">Continue to checkout</button></section>${customerNav('packages')}`; }
function checkout() { const delivery=Number(businessRules.deliveryFee||0); const total=cartTotal()+delivery; const remembered=customerProfile.name?'<p class="saved-details">Your delivery details are saved on this device.</p>':''; return `<section class="screen checkout-screen">${customerHeader('bag')}<div class="eyebrow">Almost there</div><h1>Delivery details</h1>${remembered}<form id="checkout-form" class="form-card"><label>Full name<input required name="name" value="${customerProfile.name}" placeholder="Your name"/></label><label>Phone number<input required name="phone" value="${customerProfile.phone}" placeholder="Your phone number"/></label><label>Delivery address<textarea required name="address" placeholder="House number, street, area and city">${customerProfile.address}</textarea></label><label>Delivery day<select required name="day">${['Monday','Wednesday','Friday'].map(day=>`<option ${customerProfile.day===day?'selected':''}>${day}</option>`).join('')}</select></label><label class="toggle"><input type="checkbox" name="urgent"/><span>Urgent delivery request</span></label><div class="checkout-summary"><span>${cart.reduce((n,i)=>n+i.quantity,0)} items + ${delivery?money(delivery)+' delivery':'delivery to be confirmed'}</span><b>${money(total)}</b></div><button class="button" type="submit">Place order · ${money(total)}</button></form></section>${customerNav('packages')}`; }
function confirmation() { const order=orders.find(item=>item.id===selectedOrderId); const whatsapp=businessRules.whatsApp?`<a class="support-link" href="https://wa.me/${businessRules.whatsApp}?text=Hello%20Treasures%20by%20Mudaso%2C%20my%20order%20is%20${selectedOrderId}" target="_blank">Send payment proof on WhatsApp</a>`:''; const paid=order?.paymentSubmitted; return `<section class="screen confirmation"><div class="confirmation-mark">✓</div><div class="eyebrow">Order received</div><h1>Thank you.</h1><p class="muted">Your order ${selectedOrderId} has been received. We’ll keep you updated from payment through delivery.</p><div class="payment-card"><b>Payment</b><span>${businessRules.paymentInstructions}</span></div>${whatsapp}${paid?'<div class="payment-sent">✓ Payment marked as sent — awaiting confirmation.</div>':`<button class="button secondary payment-sent-button" data-payment-sent="${selectedOrderId}">I’ve made the payment</button>`}<button class="button" data-page="orders">Track my order</button></section>`; }

function ownerHeader(title, text) { return `<header class="owner-hero"><div class="topbar">${brand()}<button class="round-button" data-page="home" aria-label="Return to customer app">×</button></div><div class="eyebrow">Owner workspace</div><h1>${title}</h1>${text ? `<p>${text}</p>` : ''}</header>`; }
function nextStatus(status) { return ({'Awaiting payment':'Payment confirmed','Payment confirmed':'Ready to pick','Ready to pick':'Picking','Picking':'Packing','Packing':'Out for delivery','Out for delivery':'Completed'})[status] || null; }
function ownerOrderRow(o) { const next=nextStatus(o.status); return `<article class="order owner-order"><div class="avatar">${o.name[0]}</div><button class="order-open" data-open-order="${o.id}"><strong>${o.name}</strong><small>${o.id} · ${o.items}</small></button><span class="status ${o.type||''}">${o.status}</span>${next?`<button class="advance-order" data-advance-order="${o.id}">${next}</button>`:''}</article>`; }
function ownerOverview() { const pending=orders.filter(o=>o.status==='Awaiting payment').length; const active=orders.filter(o=>o.status!=='Completed').length; const low=products.filter(item=>Number(item.stock)<=5).length; const urgent=orders.find(o=>o.urgent&&o.status!=='Completed'); const todayOrders=orders.filter(o=>(o.deliveryDay||'Wednesday')===ownerDeliveryDay&&o.status!=='Completed'); const expected=todayOrders.reduce((sum,o)=>sum+Number(o.total||0),0); return `<section class="screen owner-screen">${ownerHeader('Today',`${ownerDeliveryDay} delivery run`)}<div class="stats"><div class="stat"><b>${active}</b><span>orders to prepare</span></div><div class="stat"><b>${pending}</b><span>awaiting payment</span></div><div class="stat"><b>${low}</b><span>low-stock items</span></div><div class="stat"><b>${money(expected)}</b><span>expected today</span></div></div><div class="section-head"><h2>Needs attention</h2><button class="link" data-page="owner-orders">View orders</button></div>${urgent?`<div class="alert"><b>Urgent order · ${urgent.id}</b><span>Same-day delivery requested for ${urgent.address||urgent.items}. Confirm payment before picking.</span></div>`:`<div class="empty-catalogue"><b>No urgent orders right now.</b><span>Urgent customer requests will show here.</span></div>`}<div class="section-head"><h2>Next up</h2><button class="link" data-page="owner-orders">Today’s queue</button></div><div class="order-list">${todayOrders.slice(0,2).map(ownerOrderRow).join('')||'<div class="empty-catalogue"><b>No orders for this delivery day.</b><span>Use Orders to choose a different queue.</span></div>'}</div></section>${ownerNav('owner-overview')}`; }
function ownerOrders() { const queue=orders.filter(o=>(o.deliveryDay||'Wednesday')===ownerDeliveryDay); const pending=queue.filter(o=>o.status==='Awaiting payment').length; const urgent=queue.filter(o=>o.urgent&&o.status!=='Completed'); return `<section class="screen owner-screen">${ownerHeader('Orders','Manage the delivery workflow from payment to completed.')}<div class="day-tabs">${['Monday','Wednesday','Friday'].map(day=>`<button data-queue-day="${day}" class="${ownerDeliveryDay===day?'active':''}">${day}</button>`).join('')}</div><div class="queue-note"><b>${ownerDeliveryDay} queue · ${queue.length} order${queue.length===1?'':'s'}</b><span>${pending} awaiting payment · ${urgent.length} urgent</span></div>${urgent.length?urgent.map(o=>`<div class="alert"><b>Urgent · ${o.id}</b><span>${o.name} asked for priority delivery. Confirm payment before picking.</span></div>`).join(''):''}<div class="section-head"><h2>In progress</h2><span class="queue-count">${queue.filter(o=>o.status!=='Completed').length} active</span></div><div class="order-list">${queue.map(ownerOrderRow).join('')||`<div class="empty-catalogue"><b>No orders for ${ownerDeliveryDay}.</b><span>Choose another delivery day or wait for new orders.</span></div>`}</div><div class="section-head"><h2>Workflow</h2></div><div class="workflow"><span>Payment</span><i>›</i><span>Picking</span><i>›</i><span>Packing</span><i>›</i><span>Delivery</span><i>›</i><span>Completed</span></div></section>${ownerNav('owner-orders')}`; }
function ownerOrderDetail() { const o=orders.find(item=>item.id===selectedOwnerOrderId)||orders[0]; const next=nextStatus(o.status); const itemList=(o.items||'').split(', ').filter(Boolean); const picked=o.pickedItems||[]; const deliveryTeam=team.filter(member=>member.role==='Delivery person'); const deliveryOptions=deliveryTeam.length?`<option value="">Choose delivery person</option>${deliveryTeam.map(member=>`<option ${o.deliveryPerson===member.name?'selected':''}>${member.name}</option>`).join('')}`:`<option value="">Add a delivery person in Staff</option>`; const items=itemList.map((item,index)=>`<li class="${picked.includes(index)?'picked':''}"><button data-pick-item="${o.id}|${index}" aria-pressed="${picked.includes(index)}"><span class="pick-mark">${picked.includes(index)?'✓':' '}</span><span>${item}</span></button></li>`).join(''); const paymentAction=o.status==='Awaiting payment'&&o.paymentSubmitted?`<button class="button payment-confirm" data-confirm-payment="${o.id}">Confirm payment and release to picking</button>`:''; return `<section class="screen owner-screen order-detail">${ownerHeader(o.id,'Customer order and fulfilment')}<div class="detail-status"><span class="status ${o.type||''}">${o.status}</span>${o.urgent?'<b>Urgent delivery</b>':''}</div><section class="detail-block"><h2>Customer</h2><p><b>${o.name}</b><br>${o.phone||'Phone to be confirmed'}<br>${o.address||o.items}</p></section><section class="detail-block"><div class="pick-heading"><h2>Pick checklist</h2><span>${picked.length} / ${itemList.length} picked</span></div><p class="pick-help">Tap an item as it is picked and checked.</p><ul class="pick-list">${items}</ul></section><section class="detail-block"><h2>Fulfilment</h2><div class="fulfilment-grid"><span>Payment</span><b>${o.status==='Awaiting payment'?(o.paymentSubmitted?'Customer marked paid':'Awaiting confirmation'):'Confirmed'}</b><span>Delivery day</span><b>${o.deliveryDay||'Wednesday'}</b><span>Delivery person</span><b>${o.deliveryPerson||'Not assigned'}</b></div>${paymentAction}<form id="delivery-assignment-form" data-order-id="${o.id}" class="inline-form"><select name="deliveryPerson">${deliveryOptions}</select><button class="button" type="submit">Assign</button></form></section>${next?`<button class="button checkout-button" data-advance-order="${o.id}">Mark as ${next}</button>`:'<div class="completed-order">✓ Order completed</div>'}</section>${ownerNav('owner-orders')}`; }
function ownerCatalogue() { const productRows = products.length ? products.map((item,index)=>`<article class="catalogue-row"><div class="product-initial">${item.name[0]}</div><div><b>${item.name}</b><span>${item.category} · ${item.stock} in stock</span></div><button class="edit-button" data-edit-product="${index}">Edit</button></article>`).join('') : `<div class="empty-catalogue"><b>Your product list is empty.</b><span>Add the products you actually stock. They can then be used in custom packages.</span></div>`; const low=products.filter(item=>Number(item.stock)<=5); const lowRows=low.length?low.map(item=>`<article><div><b>${item.name}</b><span>${item.stock} left · restock soon</span></div><em>Low</em></article>`).join(''):`<div class="empty-catalogue"><b>No low-stock products.</b><span>Stock alerts will appear here when an item reaches five or fewer.</span></div>`; return `<section class="screen owner-screen">${ownerHeader('Catalogue','Products, packages, pricing and stock.')}<div class="quick-actions"><button class="button" data-page="add-product">Add product</button><button class="button secondary" data-page="create-package">Create package</button></div><div class="section-head"><h2>Products</h2><button class="link" data-page="add-product">Add new</button></div><div class="catalogue-products">${productRows}</div><div class="section-head"><h2>Low stock</h2><button class="link">${low.length} item${low.length===1?'':'s'}</button></div><div class="inventory-list">${lowRows}</div><div class="section-head"><h2>Packages</h2><button class="link" data-page="create-package">Add package</button></div><div class="package-mini-list">${featuredPackages.map((item,index)=>`<article><img src="${item.image}" alt=""/><div><b>${item.name}</b><span>${item.price}</span></div><button class="edit-button" data-edit-package="${index}">Edit</button></article>`).join('')}</div></section>${ownerNav('owner-catalogue')}`; }
function ownerCustomers() { const customers=[...new Map(orders.slice().reverse().map(o=>[String(o.phone||'').replace(/\D/g,'')||o.name,o])).values()]; return `<section class="screen owner-screen">${ownerHeader('Customers','A clear view of every customer and their order history.')}<div class="customer-summary"><b>${customers.length}</b><span>customers</span><b>${orders.length}</b><span>orders</span></div><div class="order-list">${customers.map(o=>`<article class="order"><div class="avatar">${o.name[0]}</div><div><strong>${o.name}</strong><small>Last order: ${o.id} · ${o.items}</small></div><span class="status">${o.status}</span></article>`).join('')}</div></section>${ownerNav('owner-customers')}`; }
function ownerMore() { return `<section class="screen owner-screen">${ownerHeader('Business controls','Team access, reports and business settings.')}<div class="settings-list"><button data-page="staff"><span>${icon('users')}</span><div><b>Staff & roles</b><small>Owner, picking and delivery responsibilities</small></div><i>›</i></button><button data-page="reports"><span>${icon('chart')}</span><div><b>Reports</b><small>Sales, bestsellers and delivery performance</small></div><i>›</i></button><button data-page="business-settings"><span>${icon('truck')}</span><div><b>Delivery & payment</b><small>Fees, instructions and customer contact</small></div><i>›</i></button></div><div class="section-head"><h2>Google Sheets</h2></div><div class="sheet-connection"><b>${sheetsEndpoint?'Your Sheet is connected':'Connect your Operations Sheet'}</b><a href="${operationsSheetUrl}" target="_blank" rel="noreferrer">Open your sheet</a><p>${sheetsEndpoint?'Load the latest products, packages, orders and staff from your Sheet whenever you need to refresh.':'Paste the Apps Script web-app link after deployment. Your Sheet stays in your Google account.'}</p><form id="sheet-connection-form"><input name="endpoint" type="url" value="${sheetsEndpoint}" placeholder="https://script.google.com/macros/s/.../exec"/><button class="button" type="submit">${sheetsEndpoint?'Update link':'Save connection'}</button></form>${sheetsEndpoint?'<button class="button secondary sheet-refresh" data-sync-sheet>Load latest from Sheet</button>':''}</div><button class="owner-lock" data-owner-lock>Lock owner workspace</button></section>${ownerNav('owner-more')}`; }
function reports() { const total=orders.reduce((sum,o)=>sum+Number(o.total||0),0); const complete=orders.filter(o=>o.status==='Completed').length; const paid=orders.filter(o=>o.status!=='Awaiting payment').length; const pending=orders.filter(o=>o.status==='Awaiting payment').length; const itemCounts={}; orders.forEach(order=>(order.items||'').split(', ').filter(Boolean).forEach(item=>{const clean=item.replace(/^\d+\s*×\s*/,'').replace(/ · .*/,'');itemCounts[clean]=(itemCounts[clean]||0)+1;})); const bestsellers=Object.entries(itemCounts).sort((a,b)=>b[1]-a[1]).slice(0,3); return `<section class="screen owner-screen">${ownerHeader('Reports','A clear snapshot of sales and fulfilment.')}<div class="stats"><div class="stat"><b>${money(total)}</b><span>order value</span></div><div class="stat"><b>${orders.length}</b><span>orders received</span></div><div class="stat"><b>${paid}</b><span>payments confirmed</span></div><div class="stat"><b>${complete}</b><span>orders completed</span></div></div><div class="report-callout ${pending?'attention':''}"><b>${pending?`${pending} payment${pending===1?'':'s'} awaiting confirmation`:'All payments are confirmed'}</b><span>${pending?'Review marked-paid orders before they enter picking.':'No payment follow-up needed right now.'}</span></div><div class="section-head"><h2>Best sellers</h2><span class="queue-count">all orders</span></div><div class="inventory-list">${bestsellers.length?bestsellers.map(([item,count],index)=>`<article><div><b>${index+1}. ${item}</b><span>${count} order${count===1?'':'s'}</span></div><em>${count}</em></article>`).join(''):'<div class="empty-catalogue"><b>Sales insights will appear here.</b><span>They build as customers place orders.</span></div>'}</div><div class="section-head"><h2>Delivery days</h2></div><div class="inventory-list">${['Monday','Wednesday','Friday'].map(day=>`<article><div><b>${day}</b><span>${orders.filter(o=>(o.deliveryDay||'Wednesday')===day).length} orders scheduled</span></div><em>View</em></article>`).join('')}</div></section>${ownerNav('owner-more')}`; }
function reportsV2() { const confirmed=orders.filter(o=>o.status!=='Awaiting payment');const completed=orders.filter(o=>o.status==='Completed');const pending=orders.filter(o=>o.status==='Awaiting payment');const confirmedValue=confirmed.reduce((sum,o)=>sum+Number(o.total||0),0);const pendingValue=pending.reduce((sum,o)=>sum+Number(o.total||0),0);const dispatchIncome=confirmed.reduce((sum,o)=>sum+Number(o.dispatchFee??businessRules.deliveryFee??0),0);const average=confirmed.length?Math.round(confirmedValue/confirmed.length):0;const completionRate=confirmed.length?Math.round(completed.length/confirmed.length*100):0;const stockValue=products.filter(p=>p.available!==false).reduce((sum,p)=>sum+Number(p.stock||0)*Number(p.price||0),0);const low=products.filter(p=>p.available!==false&&Number(p.stock||0)<=5).sort((a,b)=>Number(a.stock)-Number(b.stock));const itemCounts={};orders.forEach(order=>(order.items||'').split(', ').filter(Boolean).forEach(item=>{const clean=item.replace(/^\d+\s*×\s*/,'').replace(/ · .*/,'');itemCounts[clean]=(itemCounts[clean]||0)+(Number(item.match(/^\d+/)?.[0])||1);}));const bestsellers=Object.entries(itemCounts).sort((a,b)=>b[1]-a[1]).slice(0,4);const days=['Monday','Wednesday','Friday'];return `<section class="screen owner-screen reports-screen">${ownerHeader('Reports','The numbers that need an owner decision.')}<div class="report-grid"><article><span>Confirmed sales</span><b>${money(confirmedValue)}</b><small>${confirmed.length} paid order${confirmed.length===1?'':'s'}</small></article><article><span>Awaiting payment</span><b>${money(pendingValue)}</b><small>${pending.length} follow-up${pending.length===1?'':'s'}</small></article><article><span>Average order</span><b>${money(average)}</b><small>confirmed orders only</small></article><article><span>Completion rate</span><b>${completionRate}%</b><small>${completed.length} delivered</small></article></div><div class="report-callout ${pending.length?'attention':''}"><b>${pending.length?`${pending.length} order${pending.length===1?' is':'s are'} waiting for payment confirmation`:'All current orders have confirmed payment'}</b><span>${pending.length?'Follow up before the next picking run.':'The next priority is completing active orders.'}</span></div><div class="section-head"><h2>Dispatch & stock</h2></div><div class="report-split"><article><span>Dispatch fees recorded</span><b>${money(dispatchIncome)}</b></article><article><span>Active stock value</span><b>${money(stockValue)}</b></article></div><div class="section-head"><h2>Delivery-day sales</h2><span class="queue-count">all recorded orders</span></div><div class="report-days">${days.map(day=>{const entries=orders.filter(o=>(o.deliveryDay||'Wednesday')===day);const value=entries.filter(o=>o.status!=='Awaiting payment').reduce((sum,o)=>sum+Number(o.total||0),0);const done=entries.filter(o=>o.status==='Completed').length;return `<article><div><b>${day}</b><span>${entries.length} order${entries.length===1?'':'s'} · ${done} completed</span></div><strong>${money(value)}</strong></article>`;}).join('')}</div><div class="section-head"><h2>Best sellers</h2><span class="queue-count">by quantity ordered</span></div><div class="inventory-list">${bestsellers.length?bestsellers.map(([item,count],index)=>`<article><div><b>${index+1}. ${item}</b><span>${count} unit${count===1?'':'s'} ordered</span></div><em>${count}</em></article>`).join(''):`<div class="empty-catalogue"><b>Sales insights will appear here.</b><span>They build as customers place orders.</span></div>`}</div><div class="section-head"><h2>Restock priorities</h2><span class="queue-count">${low.length} item${low.length===1?'':'s'} low</span></div><div class="inventory-list">${low.length?low.slice(0,4).map(item=>`<article><div><b>${item.name}</b><span>${item.stock} left · ${money(Number(item.price||0)*Number(item.stock||0))} remaining stock value</span></div><em>Restock</em></article>`).join(''):`<div class="empty-catalogue"><b>Stock is in a healthy position.</b><span>No active product is at five units or fewer.</span></div>`}</div></section>${ownerNav('owner-more')}`; }
function staff() { const members=team.length?team.map(member=>`<article class="team-member"><div class="avatar">${member.name[0]}</div><div><b>${member.name}</b><span>${member.role}${member.phone?` · ${member.phone}`:''}</span></div></article>`).join(''):'<div class="empty-catalogue"><b>No team members added yet.</b><span>Add the people who pick, pack or deliver orders.</span></div>'; return `<section class="screen owner-screen">${ownerHeader('Staff & roles','Add your team and keep delivery assignments clear.')}<div class="section-head"><h2>Team</h2><span class="queue-count">${team.length} member${team.length===1?'':'s'}</span></div><div class="team-list">${members}</div><div class="section-head"><h2>Add team member</h2></div><form id="staff-form" class="form-card"><label>Full name<input required name="name" placeholder="e.g. Amina Bello"/></label><label>Role<select required name="role"><option value="">Choose a role</option><option>Picker / packer</option><option>Delivery person</option><option>Owner support</option></select></label><label>Phone number <span>(optional)</span><input name="phone" placeholder="For internal contact"/></label><button class="button" type="submit">Add team member</button></form></section>${ownerNav('owner-more')}`; }
function businessSettings() { return `<section class="screen owner-screen">${ownerHeader('Delivery & payment','Set the rules customers see at checkout.')}<form id="business-settings-form" class="form-card"><label>Standard delivery fee (₦)<input name="deliveryFee" type="number" min="0" value="${businessRules.deliveryFee||''}" placeholder="Set later if it varies by area"/></label><label>Payment instructions<textarea name="paymentInstructions" placeholder="Bank name, account name and account number, or payment instructions">${businessRules.paymentInstructions}</textarea></label><label>WhatsApp support number<input name="whatsApp" value="${businessRules.whatsApp||''}" placeholder="e.g. 2348012345678"/></label><button class="button" type="submit">Save business rules</button></form></section>${ownerNav('owner-more')}`; }
function addProduct(index) { const item = Number.isInteger(index) ? products[index] : null; const title = item ? 'Edit product' : 'Add a product'; const existingPhoto=item?.photo?`<img class="product-photo-preview" src="${item.photo}" alt="Current product photo"/>`:''; return `<section class="screen owner-screen">${ownerHeader(title,'Add the details customers need to see.')}<form id="product-form" data-product-index="${item ? index : ''}" data-existing-photo="${item?.photo || ''}" class="form-card"><label>Product name<input required name="name" value="${item?.name || ''}" placeholder="e.g. Basmati rice, 5kg"/></label><label>Category<select required name="category"><option value="">Choose a category</option>${['Pantry','Rice & grains','Household','Fresh essentials'].map(category=>`<option ${item?.category===category?'selected':''}>${category}</option>`).join('')}</select></label><div class="form-row"><label>Price (₦)<input required name="price" type="number" min="0" value="${item?.price || ''}" placeholder="0"/></label><label>Stock quantity<input required name="stock" type="number" min="0" value="${item?.stock || ''}" placeholder="0"/></label></div><label>Product photo <span>(optional)</span><input name="photoUpload" type="file" accept="image/*"/><small class="photo-help">Choose a photo from this device. No link needed.</small>${existingPhoto}</label><label class="toggle"><input name="available" type="checkbox" ${item?.available !== false ? 'checked' : ''}/><span>Available to customers</span></label><button class="button" type="submit">${item ? 'Save changes' : 'Save product'}</button></form></section>${ownerNav('owner-catalogue')}`; }
function createPackage(index) { const item = Number.isInteger(index) ? featuredPackages[index] : null; const preset=isPresetPackage(item); const selected=new Map(packageComponents(item).map(component=>[component.productId,component.quantity])); const existingPhoto=item?.image?`<img class="product-photo-preview" src="${item.image}" alt="Current package photo"/>`:''; const components=products.length?products.map(product=>`<label class="package-component"><input type="checkbox" data-package-item="${product.id}" ${selected.has(product.id)?'checked':''}/><span><b>${product.name}</b><small>${product.stock} in stock</small></span><input aria-label="Quantity of ${product.name}" data-package-qty="${product.id}" type="number" min="1" value="${selected.get(product.id)||1}"/></label>`).join(''):'<div class="empty-catalogue"><b>Add products first.</b><span>Packages are made from the products you already stock.</span></div>'; const fixedContents=`<div class="package-builder fixed-package-contents"><div><b>Official package contents</b><small>This is an approved Treasures by Mudaso package. Its contents are protected from the temporary shop catalogue.</small></div><p>${item?.contents||'Official contents will appear here.'}</p><small>When the real individual stock catalogue is ready, you can link stock items here without changing what customers see.</small></div>`; return `<section class="screen owner-screen">${ownerHeader(item ? 'Edit package' : 'Create a package',preset?'Manage sales settings for this approved package.':'Choose the stocked products and quantities inside this package.')}<form id="package-form" data-package-index="${item ? index : ''}" data-preset="${preset}" data-existing-image="${item?.image || ''}" class="form-card"><label>Package name<input required name="name" value="${item?.name || ''}" ${preset?'readonly':''} placeholder="e.g. Family essentials package"/></label><label>Package price (₦)<input required name="price" type="number" min="0" value="${item ? item.price.replace(/[^0-9]/g,'') : ''}" placeholder="0"/></label><label>Short label<input required name="tag" value="${item?.tag || ''}" ${preset?'readonly':''} placeholder="e.g. Most loved"/></label><label class="toggle"><input name="packageAvailable" type="checkbox" ${item?.available!==false?'checked':''}/><span>Package is available to customers</span></label><label class="toggle"><input name="allowInstallments" type="checkbox" ${Number(item?.installments||0)>1?'checked':''}/><span>Offer pay small small</span></label><label>Number of payments<select name="installments"><option value="2" ${Number(item?.installments)===2?'selected':''}>2 payments</option><option value="3" ${Number(item?.installments||3)===3?'selected':''}>3 payments</option><option value="4" ${Number(item?.installments)===4?'selected':''}>4 payments</option></select></label>${preset?`${existingPhoto}${fixedContents}`:`<label>Package photo <span>(optional)</span><input name="photoUpload" type="file" accept="image/*"/><small class="photo-help">Choose a photo from this device. No link needed.</small>${existingPhoto}</label><div class="package-builder"><div><b>Package contents</b><small>Select every product and set its quantity.</small></div>${components}</div>`}<button class="button" type="submit">${item ? 'Save package settings' : 'Create package'}</button></form></section>${ownerNav('owner-catalogue')}`; }

const ownerPages=['owner-overview','owner-orders','owner-order-detail','owner-catalogue','owner-customers','owner-more','business-settings','reports','staff','add-product','create-package','restock-product','delivery-manifest'];
function render(page) { const active=page || (location.hash==='#owner' ? 'owner-overview':'home'); const pages={home:homeV3,shop:shopV2,packages:packagesPageV2,'package-detail':packageDetailV2,orders:customerOrders,bag,checkout,confirmation,'owner-overview':ownerOverview,'owner-orders':ownerOrdersV3,'owner-order-detail':ownerOrderDetailV5,'owner-catalogue':ownerCatalogueV3,'owner-customers':ownerCustomers,'owner-more':ownerMoreV2,'business-settings':businessSettingsV2,reports:reportsV2,staff,'add-product':()=>addProductV2(editingProduct),'create-package':()=>createPackage(editingPackage),'restock-product':restockProductPage,'delivery-manifest':deliveryManifestV2}; if(ownerPages.includes(active)&&!ownerUnlocked){document.querySelector('#app').innerHTML=ownerGate();location.hash='owner';return;}document.querySelector('#app').innerHTML=(pages[active]||home)(); if(ownerPages.includes(active)) location.hash='owner'; else if(location.hash) history.replaceState(null,'',location.pathname+location.search); }
function showToast(message) { const toast=document.createElement('div'); toast.className='toast'; toast.textContent=message; document.body.append(toast); requestAnimationFrame(()=>toast.classList.add('visible')); setTimeout(()=>toast.remove(),5200); }
document.addEventListener('submit',async event=>{if(event.target.id!=='product-form')return;event.preventDefault();event.stopImmediatePropagation();const form=event.target;const save=photo=>{const values=Object.fromEntries(new FormData(form));delete values.photoUpload;const index=form.dataset.productIndex;const record={...values,photo,id:index===''?`PRD-${Date.now()}`:products[Number(index)].id||`PRD-${Date.now()}`,available:form.available.checked,onSale:form.onSale.checked,salePrice:Number(values.salePrice||0)};if(index==='')products.push(record);else products[Number(index)]=record;saveProducts();syncToSheet('Products',productRecord(record));editingProduct=null;showToast('Product saved to the catalogue.');render('owner-catalogue');};const file=form.photoUpload.files[0];if(!file){save(form.dataset.existingPhoto||'');return;}if(!file.type.startsWith('image/')){showToast('Please choose an image file.');return;}showToast('Uploading product photo…');try{save(await uploadProductImage(file));}catch(error){showToast(`Photo upload failed: ${error.message||'please try again'}`);}},true);
document.addEventListener('click',event=>{const detail=event.target.closest('[data-package-detail]');if(detail){selectedPackageIndex=Number(detail.dataset.packageDetail);render('package-detail');return;}const add=event.target.closest('[data-add-package]'); if(add){const [rawIndex,mode]=add.dataset.addPackage.split('|');const index=Number(rawIndex);const item=featuredPackages[index];const installments=mode==='plan'?Number(item.installments||0):0;if(installments&&cart.length){showToast('Pay small small is available for one package at a time.');return;}addToCart({id:(item.id||`package-${index}`)+(installments?'-plan':''),packageId:item.id||`package-${index}`,name:item.name,price:Number(String(item.price).replace(/[^0-9]/g,'')),image:item.image,kind:'package',installments});showToast(installments?`${item.name} added on the ${installments}-payment plan.`:`${item.name} added to your bag.`);render('packages');return;}const productAdd=event.target.closest('[data-add-product]');if(productAdd){const index=Number(productAdd.dataset.addProduct);const item=products[index];const alreadyInBag=cart.find(entry=>entry.id===item.id)?.quantity||0;if(Number(item.stock)<=alreadyInBag){showToast('That is all the stock currently available.');return;}addToCart({id:item.id||`product-${index}`,name:item.name,price:Number(item.price),image:item.photo||'',kind:'product'});showToast(`${item.name} added to your bag.`);render('shop');return;}const change=event.target.closest('[data-cart-change]');if(change){const [index,delta]=change.dataset.cartChange.split('|').map(Number);const item=cart[index];const product=item.kind==='product'?products.find(product=>product.id===item.id):null;if(delta>0&&product&&item.quantity>=Number(product.stock||0)){showToast('That is all the stock currently available.');return;}item.quantity+=delta;if(item.quantity<=0)cart.splice(index,1);saveCart();render('bag');return;}const openOrder=event.target.closest('[data-open-order]');if(openOrder){selectedOwnerOrderId=openOrder.dataset.openOrder;render('owner-order-detail');return;}const advance=event.target.closest('[data-advance-order]');if(advance){const order=orders.find(item=>item.id===advance.dataset.advanceOrder);order.status=nextStatus(order.status);saveOrders();syncToSheet('Orders',orderRecord(order));showToast(`${order.id} moved to ${order.status}.`);render('owner-order-detail');return;} const productEdit=event.target.closest('[data-edit-product]');if(productEdit){editingProduct=Number(productEdit.dataset.editProduct);render('add-product');return;}const packageEdit=event.target.closest('[data-edit-package]');if(packageEdit){editingPackage=Number(packageEdit.dataset.editPackage);render('create-package');return;}const page=event.target.closest('[data-page]')?.dataset.page;if(page){if(page==='add-product')editingProduct=null;if(page==='create-package')editingPackage=null;render(page);}});
document.addEventListener('submit',event=>{if(event.target.id==='checkout-form'){event.preventDefault();const values=Object.fromEntries(new FormData(event.target));customerProfile={name:values.name,phone:values.phone,address:values.address,day:values.day||'Wednesday'};saveCustomerProfile();const id=`TBM-${1042+orders.length+1}`;const record={id,name:values.name,phone:values.phone,address:values.address,items:cart.map(item=>`${item.quantity} × ${item.name}`).join(', '),total:cartTotal(),status:'Awaiting payment',type:'payment',paid:false,deliveryDay:values.day||'Wednesday',urgent:event.target.urgent.checked,createdAt:new Date().toISOString()};cart.filter(item=>item.kind==='product').forEach(item=>{const product=products.find(product=>product.id===item.id);if(product){product.stock=Math.max(0,Number(product.stock||0)-Number(item.quantity||0));syncToSheet('Products',productRecord(product));}});saveProducts();orders.unshift(record);selectedOrderId=id;saveOrders();syncToSheet('Orders',orderRecord(record));cart=[];saveCart();render('confirmation');return;}if(event.target.id==='tracking-form'){event.preventDefault();const requested=event.target.order.value.trim().toUpperCase();if(orders.some(order=>order.id===requested)){selectedOrderId=requested;render('orders');}else showToast('Order not found. Check the order number and try again.');return;}if(event.target.id==='sheet-connection-form'){event.preventDefault();sheetsEndpoint=event.target.endpoint.value.trim();localStorage.setItem(endpointStorageKey,sheetsEndpoint);showToast('Google Sheets connection saved.');render('owner-more');return;}if(event.target.id==='product-form'){event.preventDefault();const values=Object.fromEntries(new FormData(event.target));const index=event.target.dataset.productIndex;const record={...values,id:index===''?`PRD-${Date.now()}`:products[Number(index)].id||`PRD-${Date.now()}`,available:event.target.available.checked};if(index==='')products.push(record);else products[Number(index)]=record;saveProducts();syncToSheet('Products',productRecord(record));editingProduct=null;showToast('Product saved to the catalogue.');render('owner-catalogue');return;}if(event.target.id==='package-form'){event.preventDefault();const values=Object.fromEntries(new FormData(event.target));const index=event.target.dataset.packageIndex;const fallback=featuredPackages[Number(index)]?.image || 'assets/premium-package.jpeg';const record={id:index===''?`PKG-${Date.now()}`:featuredPackages[Number(index)].id||`PKG-${Date.now()}`,name:values.name,price:`₦${Number(values.price).toLocaleString()}`,tag:values.tag||'Curated package',image:values.image||fallback,contents:`${values.quantity} × ${values.firstItem}`};if(index==='')featuredPackages.push(record);else featuredPackages[Number(index)]=record;savePackages();syncToSheet('Packages',packageRecord(record));editingPackage=null;showToast('Package saved to the catalogue.');render('owner-catalogue');}});
document.addEventListener('submit',event=>{if(event.target.id==='delivery-assignment-form'){event.preventDefault();const order=orders.find(item=>item.id===event.target.dataset.orderId);order.deliveryPerson=event.target.deliveryPerson.value.trim()||'Not assigned';saveOrders();syncToSheet('Orders',orderRecord(order));showToast('Delivery assignment saved.');render('owner-order-detail');return;}if(event.target.id==='staff-form'){event.preventDefault();const values=Object.fromEntries(new FormData(event.target));team.push({...values,id:`STF-${Date.now()}`});saveTeam();showToast('Team member added.');render('staff');return;}if(event.target.id!=='business-settings-form')return;event.preventDefault();const values=Object.fromEntries(new FormData(event.target));businessRules={...values,deliveryFee:Number(values.deliveryFee||0)};saveRules();showToast('Delivery and payment rules saved.');render('owner-more');});
document.addEventListener('click',event=>{const track=event.target.closest('[data-track-order]');if(!track)return;selectedOrderId=track.dataset.trackOrder;render('orders');});
document.addEventListener('click',event=>{const queueDay=event.target.closest('[data-queue-day]');if(!queueDay)return;ownerDeliveryDay=queueDay.dataset.queueDay;render('owner-orders');});
document.addEventListener('click',event=>{const picked=event.target.closest('[data-pick-item]');if(!picked)return;const [orderId,itemIndex]=picked.dataset.pickItem.split('|');const order=orders.find(item=>item.id===orderId);const index=Number(itemIndex);order.pickedItems=order.pickedItems||[];order.pickedItems=order.pickedItems.includes(index)?order.pickedItems.filter(item=>item!==index):[...order.pickedItems,index];saveOrders();syncToSheet('Orders',orderRecord(order));render('owner-order-detail');});
document.addEventListener('click',event=>{const sent=event.target.closest('[data-payment-sent]');if(sent){const order=orders.find(item=>item.id===sent.dataset.paymentSent);order.paymentSubmitted=true;saveOrders();syncToSheet('Orders',orderRecord(order));showToast('Payment marked as sent. We’ll confirm it shortly.');render('confirmation');return;}const confirm=event.target.closest('[data-confirm-payment]');if(!confirm)return;const order=orders.find(item=>item.id===confirm.dataset.confirmPayment);order.status='Ready to pick';order.paid=true;saveOrders();syncToSheet('Orders',orderRecord(order));showToast('Payment confirmed. The order is now in the picking queue.');render('owner-order-detail');});
document.addEventListener('submit',event=>{if(event.target.id!=='product-form')return;event.preventDefault();event.stopImmediatePropagation();const form=event.target;const save=(photo)=>{const values=Object.fromEntries(new FormData(form));delete values.photoUpload;const index=form.dataset.productIndex;const record={...values,photo,id:index===''?`PRD-${Date.now()}`:products[Number(index)].id||`PRD-${Date.now()}`,available:form.available.checked,onSale:form.onSale.checked,salePrice:Number(values.salePrice||0)};if(index==='')products.push(record);else products[Number(index)]=record;saveProducts();syncToSheet('Products',productRecord(record));editingProduct=null;showToast('Product saved to the catalogue.');render('owner-catalogue');};const file=form.photoUpload.files[0];if(!file){save(form.dataset.existingPhoto||'');return;}if(!file.type.startsWith('image/')){showToast('Please choose an image file.');return;}const reader=new FileReader();reader.onload=()=>save(String(reader.result));reader.readAsDataURL(file);},true);
document.addEventListener('submit',event=>{if(event.target.id==='sheet-connection-form'){event.preventDefault();event.stopImmediatePropagation();sheetsEndpoint=event.target.endpoint.value.trim();localStorage.setItem(endpointStorageKey,sheetsEndpoint);showToast('Google Sheet connection saved. Loading the latest data now.');render('owner-more');if(sheetOwnerKey)loadFromSheetSecure();return;}},true);
document.addEventListener('submit',event=>{if(event.target.id==='checkout-form'){event.preventDefault();event.stopImmediatePropagation();placeCheckout(event.target);return;}if(event.target.id!=='package-form')return;event.preventDefault();event.stopImmediatePropagation();const form=event.target;const preset=form.dataset.preset==='true';const existing=featuredPackages[Number(form.dataset.packageIndex)];const components=[...form.querySelectorAll('[data-package-item]:checked')].map(control=>{const product=products.find(item=>item.id===control.dataset.packageItem);const quantity=Number(form.querySelector(`[data-package-qty="${product.id}"]`).value||1);return {productId:product.id,name:product.name,quantity};});if(!preset&&!components.length){showToast('Choose at least one product for this package.');return;}const save=image=>{const values=Object.fromEntries(new FormData(form));delete values.photoUpload;const index=form.dataset.packageIndex;const record={id:index===''?`PKG-${Date.now()}`:featuredPackages[Number(index)].id||`PKG-${Date.now()}`,preset:preset,name:values.name,price:`₦${Number(values.price).toLocaleString()}`,tag:values.tag||'Curated package',image:image||(preset?existing?.image:'assets/premium-package.jpeg'),available:form.packageAvailable.checked,components:preset?packageComponents(existing):components,installments:form.allowInstallments.checked?Number(values.installments||3):0,costPrice:Number(values.costPrice||0),contents:preset?(existing?.contents||''):components.map(component=>`${component.quantity} × ${component.name}`).join(', ')};if(index==='')featuredPackages.push(record);else featuredPackages[Number(index)]=record;savePackages();syncToSheet('Packages',packageRecord(record));editingPackage=null;showToast(preset?'Official package settings saved.':'Package saved to the catalogue.');render('owner-catalogue');};const file=form.photoUpload?.files?.[0];if(!file){save(form.dataset.existingImage||'');return;}if(!file.type.startsWith('image/')){showToast('Please choose an image file.');return;}const reader=new FileReader();reader.onload=()=>save(String(reader.result));reader.readAsDataURL(file);},true);
document.addEventListener('click',event=>{const add=event.target.closest('[data-add-package]');if(!add)return;const packageItem=featuredPackages[Number(add.dataset.addPackage)];const alreadyInBag=cart.find(item=>item.id===(packageItem.id||`package-${add.dataset.addPackage}`))?.quantity||0;const unavailable=packageComponents(packageItem).some(component=>{const product=products.find(item=>item.id===component.productId);return !product||Number(product.stock||0)<Number(component.quantity||0)*(alreadyInBag+1);});if(!unavailable)return;event.preventDefault();event.stopImmediatePropagation();showToast('One or more items in this package are out of stock.');},true);
document.addEventListener('click',event=>{const restock=event.target.closest('[data-restock-product]');if(restock){event.preventDefault();event.stopImmediatePropagation();restockingProduct=Number(restock.dataset.restockProduct);render('restock-product');return;}const archive=event.target.closest('[data-archive-product]');if(archive){event.preventDefault();event.stopImmediatePropagation();const product=products[Number(archive.dataset.archiveProduct)];if(!product)return;product.available=product.available===false;saveProducts();syncToSheet('Products',productRecord(product));showToast(product.available?'Product restored to customers.':'Product archived from customers.');render('owner-catalogue');}},true);
document.addEventListener('click',event=>{if(!event.target.closest('[data-clear-test-catalogue]'))return;event.preventDefault();event.stopImmediatePropagation();products=products.filter(item=>!item.testItem);saveProducts();showToast('Temporary test items removed.');render('owner-catalogue');},true);
document.addEventListener('submit',event=>{if(event.target.id!=='restock-form')return;event.preventDefault();event.stopImmediatePropagation();const product=products[restockingProduct];if(!product)return;const values=Object.fromEntries(new FormData(event.target));const quantity=Number(values.quantity||0);product.stock=Number(product.stock||0)+quantity;stockActivity.unshift({id:`STK-${Date.now()}`,productId:product.id,name:product.name,quantity,note:values.note||'',at:new Date().toISOString()});stockActivity=stockActivity.slice(0,50);saveProducts();saveStockActivity();syncToSheet('Products',productRecord(product));restockingProduct=null;showToast(`${quantity} added to ${product.name}.`);render('owner-catalogue');},true);
document.addEventListener('click',event=>{const advance=event.target.closest('[data-advance-order]');if(advance){event.preventDefault();event.stopImmediatePropagation();const order=orders.find(item=>item.id===advance.dataset.advanceOrder);if(!order)return;const next=nextStatus(order.status);const itemCount=(order.items||'').split(', ').filter(Boolean).length;if(order.status==='Awaiting payment'&&!order.paymentSubmitted){showToast('Wait for the customer to mark payment as sent first.');return;}if(order.status==='Picking'&&(order.pickedItems||[]).length<itemCount){showToast('Finish the pick checklist before packing.');return;}if(order.status==='Packing'&&!order.packed){showToast('Confirm the packing check before sending this order out.');return;}order.status=next;order.paid=order.status!=='Awaiting payment';saveOrders();syncToSheet('Orders',orderRecord(order));showToast(`${order.id} moved to ${order.status}.`);render('owner-order-detail');return;}const picked=event.target.closest('[data-pick-item]');if(picked){event.preventDefault();event.stopImmediatePropagation();const [orderId,itemIndex]=picked.dataset.pickItem.split('|');const order=orders.find(item=>item.id===orderId);if(!order)return;if(!['Ready to pick','Picking'].includes(order.status)){showToast('Confirm payment before starting the pick checklist.');return;}order.status='Picking';const index=Number(itemIndex);order.pickedItems=order.pickedItems||[];order.pickedItems=order.pickedItems.includes(index)?order.pickedItems.filter(item=>item!==index):[...order.pickedItems,index];const itemCount=(order.items||'').split(', ').filter(Boolean).length;const complete=itemCount>0&&order.pickedItems.length===itemCount;if(complete){order.status='Packing';order.packed=false;}saveOrders();syncToSheet('Orders',orderRecord(order));showToast(complete?'Everything is picked. Move on to packing.':'Item checked.');render('owner-order-detail');return;}const day=event.target.closest('[data-manifest-day]');if(day){event.preventDefault();ownerDeliveryDay=day.dataset.manifestDay;render('delivery-manifest');return;}if(event.target.closest('[data-print-manifest]')){window.print();}},true);
document.addEventListener('submit',event=>{if(event.target.id==='order-notes-form'){event.preventDefault();event.stopImmediatePropagation();const order=orders.find(item=>item.id===event.target.dataset.orderId);if(!order)return;const values=Object.fromEntries(new FormData(event.target));order.internalNote=values.internalNote.trim();order.substitutionNote=values.substitutionNote.trim();saveOrders();syncToSheet('Orders',orderRecord(order));showToast('Order notes saved.');render('owner-order-detail');return;}if(event.target.id==='packing-check-form'){event.preventDefault();event.stopImmediatePropagation();const order=orders.find(item=>item.id===event.target.dataset.orderId);if(!order)return;order.packed=event.target.packed.checked;saveOrders();syncToSheet('Orders',orderRecord(order));showToast(order.packed?'Packing check confirmed.':'Packing check removed.');render('owner-order-detail');}},true);
document.addEventListener('submit',event=>{if(event.target.id!=='dispatch-fee-form')return;event.preventDefault();event.stopImmediatePropagation();const order=orders.find(item=>item.id===event.target.dataset.orderId);if(!order)return;order.dispatchFee=Math.max(0,Number(event.target.dispatchFee.value||0));saveOrders();syncToSheet('Orders',orderRecord(order));showToast('Dispatch fee saved for this order.');render('owner-order-detail');},true);
