document.addEventListener('click',event=>{const sale=event.target.closest('[data-shop-sale]');if(sale){event.preventDefault();event.stopImmediatePropagation();activeShopCategory='Sale';render('shop');return;}const productAdd=event.target.closest('[data-add-product]');if(!productAdd)return;event.preventDefault();event.stopImmediatePropagation();const index=Number(productAdd.dataset.addProduct);const item=products[index];const alreadyInBag=cart.find(entry=>entry.id===item.id)?.quantity||0;if(Number(item.stock)<=alreadyInBag){showToast('This item has reached the available stock limit.');return;}addToCart({id:item.id||`product-${index}`,name:item.name,price:salePrice(item),image:item.photo||'',kind:'product'});showToast(`${item.name} added to your bag.`);render('shop');},true);
document.addEventListener('click',event=>{const start=event.target.closest('[data-start-picking]');if(start){event.preventDefault();event.stopImmediatePropagation();const order=orders.find(item=>item.id===start.dataset.startPicking);if(!order)return;order.status='Picking';saveOrders();syncToSheet('Orders',orderRecord(order));showToast('Picking started. Tick each item as you collect it.');render('owner-order-detail');return;}const finish=event.target.closest('[data-finish-packing]');if(!finish)return;event.preventDefault();event.stopImmediatePropagation();const order=orders.find(item=>item.id===finish.dataset.finishPacking);if(!order)return;order.packed=true;order.status='Out for delivery';saveOrders();syncToSheet('Orders',orderRecord(order));showToast('Packed and handed to dispatch.');render('owner-order-detail');},true);
