function ownerMoreV2() { const keyForm=`<form id="owner-sheet-key-form" class="sheet-key-form"><input name="ownerKey" type="password" value="${sheetOwnerKey}" placeholder="Private owner key" autocomplete="off"/><button class="button secondary" type="submit">Save owner key</button></form>`; const setup=`<details class="sheet-setup"><summary>Set up the live connection</summary><ol><li>Open your Sheet, then choose <b>Extensions → Apps Script</b>.</li><li>Paste the updated Apps Script file and save it.</li><li>In Apps Script settings, add a Script property called <b>OWNER_API_KEY</b> with a long private phrase.</li><li>Deploy as a Web app, copy the <b>/exec</b> link, then save that link and the same private phrase here.</li></ol><a href="google-apps-script.gs" target="_blank" rel="noreferrer">Open the ready-to-paste Apps Script</a></details>`; return ownerMore().replace('</form>','</form>'+keyForm).replace('</div><button class="owner-lock"',setup+'</div><button class="owner-lock"'); }
function loadFromSheetSecure() { if(!sheetsEndpoint||!sheetOwnerKey){showToast('Add the Apps Script link and owner key first.');return;} if(sheetLoadInProgress)return; sheetLoadInProgress=true;const callback=`treasuresSheetData${Date.now()}`;const cleanup=()=>{sheetLoadInProgress=false;delete window[callback];};window[callback]=data=>{try{if(data.ok===false)throw new Error('Owner access required');const remoteProducts=(data.products||[]).map(item=>({id:item['Product ID'],name:item.Name,category:item.Category,price:Number(item['Price (₦)']||0),salePrice:Number(item['Sale price (₦)']||0),onSale:String(item['On sale']).toLowerCase()==='true',stock:Number(item.Stock||0),available:String(item.Available).toLowerCase()!=='false',photo:item['Image URL']||''})).filter(item=>item.id);const remotePackages=(data.packages||[]).map(item=>({id:item['Package ID'],name:item.Name,price:`₦${Number(item['Price (₦)']||0).toLocaleString()}`,tag:item.Label||'Curated package',image:item['Image URL']||'assets/premium-package.jpeg',contents:item.Contents||'',components:JSON.parse(item.Components||'[]'),available:String(item.Available).toLowerCase()!=='false',installments:Number(item['Pay small small payments']||0)})).filter(item=>item.id);const remoteOrders=(data.orders||[]).map(item=>({id:clean(item['Order ID']),name:clean(item['Customer name']),phone:clean(item.Phone),address:clean(item.Address),items:clean(item.Items),total:Number(item['Total (₦)']||0),status:item['Order status']||'Awaiting payment',type:{'Awaiting payment':'payment','Packing':'packing','Out for delivery':'delivery'}[item['Order status']]||'',deliveryDay:item['Delivery day']||'Wednesday',urgent:String(item.Urgent).toLowerCase()==='true',paymentSubmitted:item['Payment status']==='Customer marked paid',paid:item['Payment status']==='Confirmed',dispatchFee:Number(item['Dispatch fee (₦)']||0),internalNote:clean(item['Internal note']),substitutionNote:clean(item['Substitution note']),packed:String(item['Packing checked']).toLowerCase()==='true',installments:Number(item['Pay small small payments']||0),installmentsPaid:Number(item['Payments confirmed']||0),balance:Number(item['Balance (₦)']??item['Total (₦)']??0),pickedItems:(()=>{try{return JSON.parse(item['Picked items']||'[]');}catch(e){return [];}})(),createdAt:item['Created at']||''})).filter(item=>item.id);const remoteTeam=(data.staff||[]).map(item=>({id:item['Staff ID'],name:item.Name,role:item.Role,phone:item.Phone||''})).filter(item=>item.id);if(Array.isArray(data.products)){products=remoteProducts;saveProducts();}if(Array.isArray(data.packages)){featuredPackages=remotePackages;savePackages();}if(Array.isArray(data.orders)){orders=remoteOrders;saveOrders();selectedOrderId=orders[0]?.id||'';selectedOwnerOrderId=orders[0]?.id||'';}if(Array.isArray(data.staff)){team=remoteTeam;saveTeam();}if(typeof onOwnerData==='function')onOwnerData(data);showToast('Latest data loaded from your Google Sheet.');render('owner-overview');}catch(error){showToast('Sheet data could not be read. Check the owner key.');}finally{cleanup();}};fetch(sheetsEndpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'dump',key:sheetOwnerKey})}).then(r=>r.json()).then(d=>window[callback]?.(d)).catch(()=>{cleanup();showToast('Could not load the Sheet yet. Check the Apps Script link.');});}
document.addEventListener('submit',event=>{if(event.target.id!=='owner-sheet-key-form')return;event.preventDefault();event.stopImmediatePropagation();sheetOwnerKey=event.target.ownerKey.value.trim();localStorage.setItem(sheetOwnerKeyStorageKey,sheetOwnerKey);showToast('Private owner key saved on this device.');render('owner-more');},true);
document.addEventListener('click',event=>{if(!event.target.closest('[data-sync-sheet]'))return;event.preventDefault();event.stopImmediatePropagation();loadFromSheetSecure();},true);
function planDue(order){return Math.min(Math.ceil(Number(order.total||0)/Number(order.installments||1)),Number(order.balance??order.total??0));}
const bagWithPlans=bag;bag=function(){const planned=cart.length===1&&Number(cart[0].installments||0)>1;const due=planned?Math.ceil(cartTotal()/cart[0].installments):cartTotal();return bagWithPlans().replace('<div class="total">',planned?`<div class="plan-summary"><span>Pay small small · ${cart[0].installments} payments</span><b>Pay today ${money(due)}</b><small>${money(cartTotal()-due)} remaining after today</small></div><div class="total">`:'<div class="total">');};
const checkoutWithPlans=checkout;checkout=function(){const planned=cart.length===1&&Number(cart[0].installments||0)>1;const delivery=Number(businessRules.deliveryFee||0);const due=planned?Math.ceil(cartTotal()/cart[0].installments)+delivery:cartTotal()+delivery;let view=checkoutWithPlans();if(planned){view=view.replace('<div class="checkout-summary">',`<div class="plan-summary"><span>Pay small small · ${cart[0].installments} payments</span><b>Pay today ${money(due)}</b><small>${money(cartTotal()-Math.ceil(cartTotal()/cart[0].installments))} remains after this payment</small></div><div class="checkout-summary">`).replace(`Place order · ${money(cartTotal()+delivery)}`,`Start plan · pay ${money(due)}`);}return view;};
const confirmationWithPlans=confirmation;confirmation=function(){const order=orders.find(item=>item.id===selectedOrderId);let view=confirmationWithPlans();if(Number(order?.installments||0)>1){const due=planDue(order);view=view.replace('<div class="payment-card">',`<div class="plan-summary"><span>Pay small small · payment ${(order.installmentsPaid||0)+1} of ${order.installments}</span><b>Send ${money(due)} today</b><small>${money(order.balance)} total balance before confirmation</small></div><div class="payment-card">`);}return view;};
function ownerOrderDetailV6(){const order=orders.find(item=>item.id===selectedOwnerOrderId)||orders[0];let view=ownerOrderDetailV5();if(Number(order.installments||0)>1){view=view.replace('</div><section class="detail-block"><h2>Customer</h2>',`</div><section class="plan-summary owner-plan"><span>Pay small small · ${order.installments} payments</span><b>${order.installmentsPaid||0} confirmed · ${money(order.balance??order.total)} remaining</b><small>${order.paymentSubmitted?`Customer marked payment ${(order.installmentsPaid||0)+1} as sent.`:'Wait for the next customer payment.'}</small></section><section class="detail-block"><h2>Customer</h2>`);}return view;}
document.addEventListener('click',event=>{const confirm=event.target.closest('[data-confirm-payment]');if(!confirm)return;const order=orders.find(item=>item.id===confirm.dataset.confirmPayment);if(!order||Number(order.installments||0)<=1)return;event.preventDefault();event.stopImmediatePropagation();if(!order.paymentSubmitted){showToast('Wait for the customer to mark this payment as sent.');return;}const due=planDue(order);order.installmentsPaid=Number(order.installmentsPaid||0)+1;order.balance=Math.max(0,Number(order.balance??order.total)-due);order.paymentSubmitted=false;if(order.balance<=0){order.status='Ready to pick';order.paid=true;showToast('Final payment confirmed. This package is ready to pick.');}else showToast(`Payment ${order.installmentsPaid} confirmed. ${money(order.balance)} remains.`);saveOrders();syncToSheet('Orders',orderRecord(order));render('owner-order-detail');},true);
const renderWithInstallmentPanel=render;render=function(page){const output=renderWithInstallmentPanel(page);if((page==='owner-order-detail'||(!page&&location.hash==='#owner'))){const order=orders.find(item=>item.id===selectedOwnerOrderId);if(order&&Number(order.installments||0)>1){const status=document.querySelector('.order-detail .detail-status');if(status&&!document.querySelector('.owner-plan'))status.insertAdjacentHTML('afterend',`<section class="plan-summary owner-plan"><span>Pay small small · ${order.installments} payments</span><b>${order.installmentsPaid||0} confirmed · ${money(order.balance??order.total)} remaining</b><small>${order.paymentSubmitted?`Customer marked payment ${(order.installmentsPaid||0)+1} as sent.`:'Wait for the next customer payment.'}</small></section>`);}}return output;};
function ownerCatalogueV3() { const testCount=products.filter(item=>item.testItem||String(item.id||'').startsWith('TEST-')).length;const note=testCount===testCatalogue.length?`<div class="test-catalogue-note"><b>Temporary catalogue active</b><span>${testCount} demo items are in the live Sheet for testing.</span><button data-clear-test-catalogue>Remove test items</button></div>`:`<div class="test-catalogue-note"><b>${testCount?'Temporary catalogue incomplete':'Catalogue ready for setup'}</b><span>${testCount?'Restore the missing demo items in the live Sheet.':'Load a temporary demo catalogue while real products are being prepared.'}</span><button data-seed-test-catalogue>${testCount?'Restore temporary catalogue':'Load temporary catalogue'}</button></div>`;return ownerCatalogueV2().replace('<div class="quick-actions">',note+'<div class="quick-actions">');}
document.addEventListener('click',async event=>{const seed=event.target.closest('[data-seed-test-catalogue]');if(!seed)return;event.preventDefault();event.stopImmediatePropagation();const missing=testCatalogue.filter(item=>!products.some(product=>product.id===item.id)).map(item=>({...item,testItem:true}));if(!missing.length){showToast('The temporary catalogue is already loaded.');return;}products=[...products,...missing];saveProducts();for(const item of missing){await syncToSheet('Products',productRecord(item));}showToast(`${missing.length} temporary products added. They will appear after the Sheet refreshes.`);render('owner-catalogue');},true);
function publicImageUrl(url) { const value=String(url||'');const id=value.match(/[?&]id=([^&]+)/)?.[1];return value.includes('drive.google.com/uc')&&id?`https://lh3.googleusercontent.com/d/${id}=w1200`:value; }
function normalizeProductImageUrls() { let changed=false;products=products.map(item=>{const photo=publicImageUrl(item.photo);if(photo!==item.photo){changed=true;return {...item,photo};}return item;});if(changed)saveProducts(); }
function cleanReportPlaceholders() { const list=document.querySelector('.reports-screen .inventory-list');if(!list)return;const rows=[...list.querySelectorAll('article')];rows.filter(row=>/^\d+\.\s+\d+\s+items?$/i.test(row.querySelector('b')?.textContent.trim()||'')).forEach(row=>row.remove());[...list.querySelectorAll('article b')].forEach((title,index)=>{title.textContent=title.textContent.replace(/^\d+\.\s*/,`${index+1}. `);}); }
const renderWithNormalizedImages=render;
render=function(page) { normalizeProductImageUrls();const output=renderWithNormalizedImages(page);document.querySelectorAll('#product-form .photo-help').forEach(help=>{if(!help.textContent.includes('selected'))help.textContent='Any phone photo is fine — we resize it automatically before upload.';});cleanReportPlaceholders();return output; };
let ownerWorkspacePage='owner-overview';
const renderWithOwnerContinuity=render;
render=function(page) { const requested=page || (location.hash==='#owner'?ownerWorkspacePage:'home'); if(ownerPages.includes(requested))ownerWorkspacePage=requested; const shouldStayInOwner=ownerUnlocked&&location.hash==='#owner'&&requested==='home'; return renderWithOwnerContinuity(shouldStayInOwner?ownerWorkspacePage:requested); };
let renderedAppPage=location.hash==='#owner'?'owner-overview':'home';
let customerHomeRequestAt=0;
