const renderWithRefreshStability=render;
render=function(page) { const requested=page || (location.hash==='#owner'?ownerWorkspacePage:'home'); const isBackgroundHomeRefresh=!ownerUnlocked&&requested==='home'&&renderedAppPage!=='home'&&publicCatalogueLoaded&&Date.now()-customerHomeRequestAt>800; const isBackgroundOwnerRefresh=ownerUnlocked&&requested==='owner-overview'&&ownerWorkspacePage!=='owner-overview'&&sheetLoadInProgress; if(isBackgroundHomeRefresh)return; renderedAppPage=requested; return renderWithRefreshStability(isBackgroundOwnerRefresh?ownerWorkspacePage:requested); };
const addToCartWithRouteMemory=addToCart;
addToCart=function(item) { if(['shop','packages','package-detail'].includes(renderedAppPage)){cartReturnPage=renderedAppPage==='package-detail'?'packages':renderedAppPage;localStorage.setItem(cartReturnPageKey,cartReturnPage);} return addToCartWithRouteMemory(item); };
const bagWithReturnRoute=bag;
bag=function() { const view=bagWithReturnRoute(); return cart.length?view.replace(customerHeader('packages'),customerHeader(cartReturnPage)).replace(customerNav('packages'),customerNav(cartReturnPage)):view; };
const deliveryDays=['Monday','Wednesday','Friday'];
function nextAvailableDeliveryDay(now=new Date()) { const today=now.getDay(); const schedule=[{day:1,name:'Monday'},{day:3,name:'Wednesday'},{day:5,name:'Friday'}]; return schedule.map(entry=>({...entry,wait:(entry.day-today+7)%7})).sort((a,b)=>a.wait-b.wait)[0].name; }
function deliveryDaySelector() { const next=nextAvailableDeliveryDay(); const choice=customerProfile.deliveryChoice||'next'; return `<label>Delivery day<select required name="day"><option value="next" ${choice==='next'?'selected':''}>Next available · ${next}</option>${deliveryDays.map(day=>`<option value="${day}" ${choice===day?'selected':''}>${day}</option>`).join('')}</select><small class="delivery-help">Choose the next available run, or select Monday, Wednesday or Friday.</small></label>`; }
const checkoutWithDeliveryChoice=checkout;
checkout=function() { return checkoutWithDeliveryChoice().replace(/<label>Delivery day<select required name="day">.*?<\/select><\/label>/,deliveryDaySelector()); };
const placeCheckoutWithDeliveryChoice=placeCheckout;
placeCheckout=async function(form) { const chosenDay=form.elements.day?.value||'next'; if(chosenDay==='next'){const select=form.elements.day;const next=nextAvailableDeliveryDay();if(![...select.options].some(o=>o.value===next))select.add(new Option(next,next));select.value=next;} await placeCheckoutWithDeliveryChoice(form); customerProfile={...customerProfile,deliveryChoice:chosenDay}; saveCustomerProfile(); };
function checkoutImage(item) { return item?.image||fallbackProductPhoto(item?.id,'')||'assets/reference/package-products.png'; }
function checkoutOrderPreview() { if(!cart.length)return ''; return `<section class="checkout-order-preview"><div><span>Your order</span><b>${cart.reduce((total,item)=>total+Number(item.quantity||0),0)} item${cart.reduce((total,item)=>total+Number(item.quantity||0),0)===1?'':'s'}</b></div><div class="checkout-preview-images">${cart.slice(0,3).map(item=>`<img src="${checkoutImage(item)}" alt="${item.name}"/>`).join('')}</div></section>`; }
const checkoutWithOrderPreview=checkout;
checkout=function() { return checkoutWithOrderPreview().replace('<form id="checkout-form"',`${checkoutOrderPreview()}<form id="checkout-form"`); };
document.addEventListener('error',event=>{const image=event.target;if(!(image instanceof HTMLImageElement)||image.dataset.fallbackApplied)return;image.dataset.fallbackApplied='true';const alt=String(image.alt||'').toLowerCase();image.src=alt.includes('healthy')?'assets/healthy-package.jpeg':alt.includes('all inclusive')?'assets/all-inclusive-package.jpeg':alt.includes('package')?'assets/premium-package.jpeg':'assets/reference/package-products.png';},true);
const customerOrdersWithEmptyState=customerOrders;
customerOrders=function() { if(orders.length)return customerOrdersWithEmptyState(); return `<section class="screen orders-screen">${customerHeader('home')}<div class="eyebrow">My orders</div><h1>Track your order</h1><p class="muted">Enter an order number to check its progress on this device.</p><form id="tracking-form" class="track-form"><input aria-label="Order number" name="order" placeholder="e.g. TBM-1042"/><button class="button" type="submit">Track order</button></form><div class="empty-catalogue"><b>No orders on this device yet.</b><span>Your placed orders will appear here.</span></div></section>${customerNav('orders')}`; };
const customerOrdersWithSecureTracking=customerOrders;
customerOrders=function(){
  const view=customerOrdersWithSecureTracking();
  const phoneField=`<input aria-label="Phone number used for this order" name="phone" inputmode="tel" value="${customerProfile.phone||''}" placeholder="Phone number used for this order"/>`;
  return view.replace(/(<input[^>]*name="order"[^>]*\/>)/,`$1${phoneField}`);
};
function trackOrderFromSheet(orderId,phone){
  if(!publicSheetsEndpoint){showToast('Order tracking is not connected yet.');return;}
  const callback=`treasuresOrderTrack${Date.now()}`;
  const cleanup=()=>delete window[callback];
  window[callback]=data=>{
    try{
      if(!data?.found||!data.order){showToast('Order not found. Check the order number and phone number.');return;}
      const tracked={...data.order,name:'',phone:'',address:'',total:0,type:'payment',paid:data.order.status!=='Awaiting payment',paymentSubmitted:false};
      orders=[tracked,...orders.filter(item=>item.id!==tracked.id)];
      selectedOrderId=tracked.id;
      saveOrders();
      render('orders');
    } finally { cleanup(); }
  };
  const script=document.createElement('script');
  script.src=`${publicSheetsEndpoint}?action=track&order=${encodeURIComponent(orderId)}&phone=${encodeURIComponent(phone)}&callback=${callback}&t=${Date.now()}`;
  script.onerror=()=>{cleanup();showToast('Order tracking is unavailable right now. Please try again.');};
  document.head.append(script);
}
document.addEventListener('submit',event=>{
  if(event.target.id!=='tracking-form')return;
  event.preventDefault();
  event.stopImmediatePropagation();
  const orderId=event.target.order.value.trim().toUpperCase();
  const phone=event.target.phone?.value.trim()||'';
  if(orders.some(order=>order.id===orderId)){selectedOrderId=orderId;render('orders');return;}
  if(!orderId||!phone){showToast('Enter the order number and the phone number used for the order.');return;}
  trackOrderFromSheet(orderId,phone);
},true);
const ownerOrderDetailWithEmptyState=ownerOrderDetailV5;
ownerOrderDetailV5=function() { if(orders.length)return ownerOrderDetailWithEmptyState(); return `<section class="screen owner-screen">${ownerHeader('Orders','Customer orders will appear here as they are placed.')}<div class="empty-catalogue"><b>No orders yet.</b><span>Your next customer order will appear in the relevant delivery queue.</span></div></section>${ownerNav('owner-orders')}`; };
loadPublicCatalogue();
// Keep staff changes durable: the original form updated this device but did not
// write the new person to the connected operations Sheet.
document.addEventListener('submit',event=>{
  if(event.target.id!=='staff-form')return;
  event.preventDefault();
  event.stopImmediatePropagation();
  const values=Object.fromEntries(new FormData(event.target));
  const member={...values,id:`STF-${Date.now()}`};
  team.push(member);
  saveTeam();
  syncToSheet('Staff',staffRecord(member));
  showToast('Team member added and saved to your Sheet.');
  render('staff');
},true);
document.addEventListener('click',async event=>{if(!event.target.closest('[data-install-app]'))return;if(!deferredInstallPrompt){showToast('Use your browser menu and choose “Add to Home Screen”.');return;}deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;showToast('Treasures has been added to this device.');});
document.addEventListener('change',event=>{if(!event.target.matches('#product-form input[name="photoUpload"]'))return;const file=event.target.files&&event.target.files[0];const helper=event.target.closest('label')?.querySelector('.photo-help');if(!file){if(helper)helper.textContent='Choose a photo from this device. No link needed.';return;}if(helper)helper.textContent=`${file.name} selected — tap Save changes to upload it.`;showToast('Photo selected. Tap Save changes to upload it.');},true);
document.addEventListener('click',async event=>{const sent=event.target.closest('[data-payment-sent]');if(!sent)return;event.preventDefault();event.stopImmediatePropagation();const order=orders.find(o=>o.id===sent.dataset.paymentSent);if(!order)return;sent.disabled=true;try{const res=await postPublic({action:'markPaid',order:order.id,phone:order.phone||customerProfile.phone});if(!res.ok){showToast(res.error||'Could not update payment.');sent.disabled=false;return;}}catch(e){showToast('No connection. Please try again.');sent.disabled=false;return;}order.paymentSubmitted=true;saveOrders();showToast('Payment marked as sent. We’ll confirm it shortly.');render('confirmation');},true);
document.addEventListener('submit',event=>{if(event.target.id!=='business-settings-form'||!sheetsEndpoint||!sheetOwnerKey)return;const v=Object.fromEntries(new FormData(event.target));fetch(sheetsEndpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'saveSettings',key:sheetOwnerKey,...v})}).then(r=>r.json()).then(res=>{if(!res.ok)showToast('Settings saved here but not on the server. Check the owner key.');}).catch(()=>showToast('Settings saved here but not on the server.'));},true);
document.addEventListener('submit',async event=>{if(event.target.id!=='owner-gate-form')return;event.preventDefault();event.stopImmediatePropagation();const form=event.target;const pin=form.elements.pin.value.trim();if(!/^\d{4,8}$/.test(pin)){showToast('Use a 4–8 digit access code.');return;}const hashed=await hashPin(pin);const stored=localStorage.getItem(ownerPinKey);if(form.dataset.mode==='setup'){if(pin!==form.elements.confirmPin.value.trim()){showToast('The access codes do not match.');return;}localStorage.setItem(ownerPinKey,hashed);}else if(stored!==hashed&&stored!==pin){showToast('That access code is not correct.');return;}else if(stored===pin)localStorage.setItem(ownerPinKey,hashed);ownerUnlocked=true;sessionStorage.setItem(ownerSessionKey,'true');render('owner-overview');},true);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
